  border-color: color-mix(in srgb, var(--kv-accent) 16%, var(--kv-border));
  background:
    radial-gradient(ellipse at 87% 14%, color-mix(in srgb, var(--kv-accent) 12%, transparent), transparent 38%),
    linear-gradient(135deg, var(--kv-surface) 0%, color-mix(in srgb, var(--kv-neon) 6%, var(--kv-surface)) 100%);
