}
.kv-hero:hover .kv-cover-wrap { transform: rotate(0) translateY(-3px); }
.kv-kicker { color: var(--kv-accent); letter-spacing: 0.12em; }
.kv-section { margin-top: 60px; }
.kv-section-head { margin-bottom: 22px; }
.kv-section-title { font-size: 1.45rem; letter-spacing: -0.045em; }
.kv-grid { gap: 22px; }
.kv-card {
  border-radius: 17px;
