}
.kv-card-body { padding: 16px; gap: 9px; }
.kv-card-title { font-size: 0.98rem; letter-spacing: -0.035em; }
.kv-chip {
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--kv-surface-2);
