  background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
}
.kv-toolbar {
  padding: 18px;
  gap: 12px;
  border-radius: 17px;
  box-shadow: 0 10px 28px -26px rgba(30, 35, 60, 0.55);
}
.kv-input, .kv-select, .kv-textarea {
  min-height: 44px;
