}
.kv-detail-grid > .kv-cover-wrap {
  border-radius: 21px;
  box-shadow: 0 22px 52px -32px rgba(30, 35, 60, 0.55);
}
.kv-detail-grid h1 { letter-spacing: -0.065em; line-height: 1.08; }
.kv-chapter-row {
  min-height: 58px;
  border: 1px solid var(--kv-border);
  border-radius: 13px;
  margin-bottom: 9px;
  padding: 13px 16px;
  background: var(--kv-surface);
  transition: border-color 0.16s ease, background-color 0.16s ease, transform 0.16s ease;
}
.kv-chapter-row:last-child { margin-bottom: 0; }
.kv-chapter-row:hover {
  border-color: color-mix(in srgb, var(--kv-accent) 42%, var(--kv-border));
  background: color-mix(in srgb, var(--kv-accent) 4%, var(--kv-surface));
  transform: translateY(-1px);
}
.kv-stat-box, .kv-table-wrap {
  border-radius: 16px;
  border-color: var(--kv-border);
  box-shadow: 0 10px 30px -27px rgba(30, 35, 60, 0.52);
}
.kv-table-wrap { overflow-x: auto; }
table.kv-table { border-spacing: 0; }
table.kv-table th {
  color: var(--kv-text-muted);
  background: var(--kv-surface-2);
  font-size: 0.7rem;
  letter-spacing: 0.075em;
}
table.kv-table td { vertical-align: middle; }
table.kv-table tbody tr:last-child td { border-bottom: 0; }
table.kv-table tbody tr:hover { background: color-mix(in srgb, var(--kv-accent) 4%, var(--kv-surface)); }
.kv-footer {
  margin-top: 88px;
  background: color-mix(in srgb, var(--kv-surface) 80%, transparent);
  border-top-color: var(--kv-border);
}
.kv-footer a { transition: color 0.15s ease; }
.kv-footer a:hover { color: var(--kv-accent); }
.kv-admin-shell { background: var(--kv-bg); }
.kv-admin-side {
  width: 260px;
  padding: 24px 16px;
  background: var(--kv-surface);
  border-right-color: var(--kv-border);
}
.kv-admin-logo { padding: 5px 10px 20px; font-size: 1.12rem; }
.kv-admin-logo span { color: var(--kv-accent); }
.kv-admin-side-label { letter-spacing: 0.09em; }
.kv-admin-nav { gap: 5px; }
.kv-admin-nav-item {
  min-height: 42px;
  border-radius: 11px;
  transition: color 0.16s ease, background-color 0.16s ease;
}
.kv-admin-nav-item.active {
  color: var(--kv-accent);
  background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
