   html:not(.dark) body.kv-home-route {
     --kv-bg: #f4ecd8;
     --kv-surface: #faf3e0;
     --kv-surface-2: #efe4c8;
     --kv-border: #d8c8a0;
     --kv-text: #3b2f1e;
     --kv-text-muted: #6b5b3e;
     --kv-accent: #8b5a2b;
     --kv-accent-hover: #6b4423;
     --kv-success: #10b981;
     --kv-warning: #f59e0b;
     --kv-danger: #ef4444;
     --kv-radius: 16px;
     background: #f4ecd8;

    -webkit-font-smoothing: antialiased;
  }
  html:not(.dark) body.kv-home-route .kv-container { max-width: 1280px; }
  html:not(.dark) body.kv-home-route .kv-header {
    background: rgba(250, 243, 224,.96); backdrop-filter: blur(14px); border-bottom: 1px solid #d8c8a0;
    position: sticky; top: 0; z-index: 30; box-shadow: 0 1px 2px rgba(59, 47, 30,.04);
  }
