  html:not(.dark) body.kv-home-route .kv-nav a.active { background: #f0e6cc; color: #8b5a2b; }
  html:not(.dark) body.kv-home-route .kv-theme-toggle, html:not(.dark) body.kv-home-route .kv-mobile-btn { background: transparent; border: none; color: #6b5b3e; }
  html:not(.dark) body.kv-home-route .kv-theme-toggle:hover, html:not(.dark) body.kv-home-route .kv-mobile-btn:hover { background: #efe4c8; color: #8b5a2b; }
  html:not(.dark) body.kv-home-route .kv-footer { background: #faf3e0; border-top: 1px solid #d8c8a0; color: #5a4a32; }
  html:not(.dark) body.kv-home-route .kv-footer a { color: #5a4a32; }
  html:not(.dark) body.kv-home-route .kv-footer a:hover { color: #8b5a2b; }
  body.kv-home-route .kv-home-banner { position: relative; margin: 14px 0 18px; }
  body.kv-home-route .kv-home-banner-track { display: flex; gap: 16px; overflow-x: auto; scroll-snap-type: x mandatory; scroll-behavior: smooth; padding: 4px 2px 10px; scrollbar-width: none; -ms-overflow-style: none; border-radius: 24px; }
  body.kv-home-route .kv-home-banner-track::-webkit-scrollbar { display: none; }
  body.kv-home-route .kv-home-banner-card { position: relative; flex: 0 0 100%; height: clamp(240px, 34vw, 360px); border-radius: 22px; overflow: hidden; text-decoration: none; color: #f4f4f6; scroll-snap-align: center; background: #14141c; box-shadow: 0 26px 60px -30px rgba(6,6,12,.65); display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: 100%; }
  body.kv-home-route .kv-home-banner-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
