  body.kv-home-route .kv-home-banner-overlay { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(10,10,16,.88) 0%, rgba(10,10,16,.55) 55%, rgba(10,10,16,0) 100%); }
  body.kv-home-route .kv-home-banner-body { position: relative; z-index: 1; grid-column: 1 / 2; align-self: center; display: flex; flex-direction: column; gap: 10px; padding: 26px; text-shadow: 0 4px 18px rgba(0,0,0,.55); max-width: 100%; }
  body.kv-home-route .kv-home-banner-title { margin: 0; font-size: clamp(1.4rem, 3vw, 2rem); line-height: 1.15; font-weight: 800; letter-spacing: -0.02em; color: #fff; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
  body.kv-home-route .kv-home-banner-meta { display: flex; flex-wrap: wrap; gap: 14px; font-size: .8rem; color: rgba(255,255,255,.88); }
  body.kv-home-route .kv-home-banner-cta { display: inline-flex; align-items: center; gap: 8px; width: max-content; margin-top: 2px; padding: 11px 20px; border-radius: 12px; background: var(--kv-accent); color: #fff; font-size: .85rem; font-weight: 700; text-decoration: none; box-shadow: 0 14px 28px -14px rgba(99,102,241,.75); transition: transform .15s ease, filter .15s ease; }
  body.kv-home-route .kv-home-banner-cta:hover { transform: translateY(-2px); filter: brightness(1.08); }
