  body.kv-home-route .kv-home-banner-dot.is-active { width: 36px; background: var(--kv-accent); box-shadow: 0 6px 16px -8px var(--kv-accent); }
  body.kv-home-route .kv-home-banner-poster { position: static; grid-column: 2 / 3; height: calc(100% - 28px); margin: 14px 14px 14px 0; aspect-ratio: 3 / 4; object-fit: cover; border-radius: 16px; border: 1px solid rgba(255,255,255,.2); box-shadow: 0 20px 46px -16px rgba(0,0,0,.7); z-index: 1; }
  body.kv-home-route .kv-home-banner-poster-empty { display: grid; place-items: center; background: linear-gradient(135deg,#1f2937 0%,#374151 100%); color: rgba(255,255,255,.55); font-size: .72rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
  @media (max-width: 760px) {
    body.kv-home-route .kv-home-banner-card { height: clamp(190px, 56vw, 300px); border-radius: 16px; }
    body.kv-home-route .kv-home-banner-body { padding: 14px; gap: 6px; }
    body.kv-home-route .kv-home-banner-poster { height: calc(100% - 20px); margin: 10px 10px 10px 0; border-radius: 12px; }
    body.kv-home-route .kv-home-banner-title { font-size: clamp(1.1rem, 5.2vw, 1.5rem); -webkit-line-clamp: 2; }
    body.kv-home-route .kv-home-banner-cta { padding: 9px 14px; font-size: .78rem; max-width: 100%; }
  }
  html:not(.dark) body.kv-home-route .kv-home-genres { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 10px; margin: 22px 0 10px; }
