   .kv-comment-rules { margin: 0 0 20px; padding: 12px 14px; border: 0; border-left: 4px solid var(--kv-accent); border-radius: 0; background: transparent; }
   .kv-comment-reaction { margin: 16px 0 24px; padding: 14px 12px; border: 0; border-radius: 0; background: transparent; }
   .kv-comment-form { margin-top: 8px; }
   .kv-comment-sortbar { display: flex; align-items: center; gap: 8px; margin: 12px 0 8px; }
   .kv-comment-sortlabel { font-size: .75rem; color: var(--kv-text-muted); font-weight: 700; }

.kv-comment-rules-head { display:flex; align-items:center; gap:8px; font-size:.78rem; font-weight:800; color:var(--kv-text); letter-spacing:.04em; text-transform:uppercase; margin-bottom:8px; }
.kv-comment-rules-head svg { width:16px; height:16px; display:block; color:var(--kv-accent); }
.kv-comment-rules-list { margin:0; padding-left:18px; display:grid; gap:4px; font-size:.8rem; line-height:1.5; color:var(--kv-text-muted); }
   .kv-comment-reaction { margin: 4px 0 12px; padding: 14px 12px; border: 0; border-radius: 0; background: transparent; }

.kv-comment-reaction-label { font-size: .72rem; font-weight: 700; color: var(--kv-text-muted); text-transform: uppercase; letter-spacing: .06em; margin-bottom: 10px; text-align: center; }
.kv-manga-reaction-row { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; max-width: 480px; margin: 0 auto; }
.kv-manga-reaction { flex: 0 0 calc(33.333% - 8px); max-width: 150px; min-width: 110px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; padding: 12px 8px; border-radius: 14px; border: 1px solid var(--kv-border); background: var(--kv-surface-2); color: var(--kv-text-muted); cursor: pointer; transition: border-color .15s ease, transform .15s ease, color .15s ease, background-color .15s ease; }
.kv-manga-reaction:hover { transform: translateY(-2px); border-color: var(--kv-accent); color: var(--kv-text); }
.kv-manga-reaction.active { border-color: var(--kv-accent); color: var(--kv-accent); background: color-mix(in srgb, var(--kv-accent) 12%, var(--kv-surface)); }
.kv-manga-reaction-emoji { font-size: 1.5rem; line-height: 1; }
.kv-manga-reaction-count { font-size: .82rem; font-weight: 800; font-variant-numeric: tabular-nums; }
.kv-manga-reaction-label { font-size: .7rem; font-weight: 600; text-align: center; line-height: 1.2; }
.kv-manga-reaction-static { cursor: default; }
.kv-comment-toggle-replies { display: inline-flex; align-items: center; gap: 6px; margin-top: 8px; padding: 6px 10px; border-radius: 8px; border: 1px solid var(--kv-border); background: transparent; color: var(--kv-accent); font-size: .74rem; font-weight: 700; cursor: pointer; transition: background-color .15s ease, border-color .15s ease; }
.kv-comment-toggle-replies:hover { background: color-mix(in srgb, var(--kv-accent) 10%, transparent); border-color: var(--kv-accent); }
.kv-comment-toggle-replies svg { width: 14px; height: 14px; transition: transform .2s ease; }
.kv-comment-toggle-replies.is-open svg { transform: rotate(180deg); }
.kv-comment-action svg { width:16px; height:16px; }

.kv-comment-scope-note { margin:0 0 10px; font-size:.74rem; color:var(--kv-text-muted); }
.kv-comment-chapter-badge { display:inline-flex; align-items:center; padding:1px 7px; border-radius:6px; background:color-mix(in srgb, var(--kv-accent) 12%, var(--kv-surface)); color:var(--kv-accent); font-size:.64rem; font-weight:700; letter-spacing:.02em; }
.kv-comment-pinned { display:inline-flex; align-items:center; gap:4px; padding:2px 8px; border-radius:999px; background:color-mix(in srgb, var(--kv-accent) 14%, var(--kv-surface)); color:var(--kv-accent); font-size:.62rem; font-weight:800; text-transform:uppercase; letter-spacing:.05em; }
.kv-comment-pinned svg { width:12px; height:12px; display:block; }
.kv-comment-action-danger { color:var(--kv-text-muted); }
.kv-comment-action-danger:hover { color:#ef4444; border-color:#ef4444; }
@media (max-width: 520px) {

}
.kv-comment-image { max-width: 100%; max-height: 360px; border-radius: 12px; display: block; margin-top: 8px; border: 1px solid var(--kv-border); object-fit: cover; }
  .kv-comment-image-btn { display: inline-flex; align-items: center; justify-content: center; width: 38px; height: 38px; padding: 0; }
  .kv-comment-image-btn svg { width: 18px; height: 18px; display: block; }
  .kv-spoiler { border: 1px solid var(--kv-border); border-radius: 10px; margin: 8px 0; overflow: hidden; background: var(--kv-surface-2); }
  .kv-spoiler-toggle { display: flex; align-items: center; gap: 8px; width: 100%; padding: 10px 12px; background: transparent; border: 0; color: var(--kv-text-muted); font-size: .78rem; font-weight: 600; cursor: pointer; text-align: left; }
  .kv-spoiler-toggle:hover { background: color-mix(in srgb, var(--kv-accent) 10%, transparent); color: var(--kv-text); }
  .kv-spoiler-body { display: none; padding: 12px; border-top: 1px solid var(--kv-border); color: var(--kv-text); background: var(--kv-surface); white-space: pre-wrap; }
  .kv-spoiler.open .kv-spoiler-body { display: block; }
  .kv-spoiler-state-close { display: none; }
  .kv-spoiler.open .kv-spoiler-state-close { display: inline; }
  .kv-spoiler.open .kv-spoiler-state-open { display: none; }
   .kv-reply-to { display: inline-flex; align-items: center; background: rgba(101,88,217,.18); color: var(--kv-accent); padding: 2px 7px; border-radius: 999px; font-size: .68rem; font-weight: 600; margin-right: 6px; }
   .kv-traffic { margin-top: 20px; }
   .kv-traffic-toolbar { display: flex; align-items: end; gap: 14px; flex-wrap: wrap; background: var(--kv-surface); padding: 14px 16px; border-radius: 13px; margin-bottom: 20px; border: 1px solid var(--kv-border); }
   .kv-traffic-field { display: flex; flex-direction: column; gap: 7px; min-width: 150px; flex: 1; }
   .kv-traffic-field label { font-size: 11px; color: var(--kv-text-muted); letter-spacing: .04em; font-weight: 700; }
   .kv-traffic-field select, .kv-traffic-field input { height: 38px; border: 1px solid var(--kv-border); background: var(--kv-surface-2); color: var(--kv-text); border-radius: 7px; padding: 0 10px; font-size: 12px; }
   .kv-traffic-cards { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 18px; margin-bottom: 20px; }
   .kv-traffic-card { position: relative; overflow: hidden; background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 13px; padding: 22px 22px 18px; min-height: 132px; }
   .kv-traffic-card:before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--kv-accent); }
   .kv-traffic-card:nth-child(2):before { background: #9b91ff; }
   .kv-traffic-card:nth-child(3):before { background: #e3c96a; }
   .kv-traffic-card:nth-child(4):before { background: #68c9b0; }
   .kv-traffic-label { font-size: 11px; letter-spacing: .055em; color: var(--kv-text-muted); font-weight: 700; }
   .kv-traffic-value { font-size: 29px; font-weight: 750; letter-spacing: -.03em; margin: 14px 0 7px; color: var(--kv-text); }
   .kv-traffic-note { font-size: 10px; color: var(--kv-text-muted); }
   .kv-traffic-chart { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 14px; padding: 22px; }
   .kv-traffic-legend { display: flex; justify-content: center; gap: 20px; flex-wrap: wrap; margin: 25px 0 7px; font-size: 10px; color: var(--kv-text-muted); }
   .kv-traffic-legend span { display: flex; align-items: center; gap: 6px; }
   .kv-traffic-dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }
   .kv-traffic-grid { stroke: var(--kv-border); stroke-width: 1; opacity: .65; }
   .kv-traffic-axis { fill: var(--kv-text-muted); font-size: 10px; }
   .kv-traffic-line { fill: none; stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }
   @media (max-width: 800px) { .kv-traffic-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
   @media (max-width: 460px) { .kv-traffic-cards { grid-template-columns: 1fr 1fr; } .kv-traffic-value { font-size: 24px; } }
   .kv-admin-chapter-card { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 10px; padding: 12px 14px; display: flex; flex-direction: column; gap: 10px; }
   .kv-admin-chapter-card-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
   .kv-admin-chapter-card-title { flex: 1; min-width: 0; font-weight: 600; color: var(--kv-text); font-size: .9rem; overflow-wrap: anywhere; }
   .kv-admin-chapter-card-date { color: var(--kv-text-muted); font-size: .75rem; }
   .kv-admin-chapter-card-progress { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
   .kv-admin-chapter-card-bar { flex: 1; min-width: 120px; height: 6px; background: var(--kv-surface-2); border-radius: 999px; overflow: hidden; }
   .kv-admin-chapter-card-barfill { height: 100%; background: var(--kv-accent); border-radius: 999px; }
   .kv-admin-chapter-card-actions { display: flex; gap: 6px; flex-wrap: wrap; }
   .kv-admin-chapter-card-list { display: flex; flex-direction: column; gap: 10px; margin-top: 16px; }
   .kv-spinner { display: inline-block; width: 16px; height: 16px; border: 2px solid var(--kv-border); border-top-color: var(--kv-accent); border-radius: 50%; animation: kv-spin .7s linear infinite; }
   @keyframes kv-spin { to { transform: rotate(360deg); } }
   .kv-upload-overlay { position: fixed; inset: 0; background: rgba(0,0,0,.6); backdrop-filter: blur(2px); display: flex; align-items: center; justify-content: center; z-index: 9999; }
   .kv-upload-box { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 12px; padding: 24px 28px; min-width: 320px; max-width: 90vw; text-align: center; box-shadow: 0 10px 40px rgba(0,0,0,.4); }
   .kv-upload-title { font-weight: 700; font-size: 1.1rem; color: var(--kv-text); margin-bottom: 6px; }
   .kv-upload-sub { color: var(--kv-text-muted); font-size: .8rem; margin-bottom: 14px; overflow-wrap: anywhere; }
   .kv-upload-bar { height: 8px; background: var(--kv-surface-2); border-radius: 999px; overflow: hidden; margin-bottom: 10px; }
   .kv-upload-bar-fill { height: 100%; background: var(--kv-accent); border-radius: 999px; transition: width .2s ease; }
   .kv-upload-count { color: var(--kv-text-muted); font-size: .8rem; }
   .kv-admin-comments { display: flex; flex-direction: column; gap: 14px; }
   .kv-admin-comment-filters { display: flex; gap: 8px; flex-wrap: wrap; }
   .kv-admin-comment-count { opacity: .7; font-size: .7rem; }
   .kv-admin-comment-list { display: flex; flex-direction: column; gap: 10px; }
   .kv-admin-comment-card { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 10px; padding: 12px 14px; display: flex; flex-direction: column; gap: 10px; }
   .kv-admin-comment-card.is-pinned { border-color: var(--kv-accent); box-shadow: 0 0 0 1px rgba(101,88,217,.25); }
   .kv-admin-comment-head { display: flex; align-items: center; gap: 10px; }
   .kv-admin-comment-avatar { width: 36px; height: 36px; border-radius: 50%; object-fit: cover; flex: 0 0 36px; }
   .kv-admin-comment-avatar-fallback { display: flex; align-items: center; justify-content: center; background: var(--kv-surface-2); color: var(--kv-text); font-weight: 700; }
   .kv-admin-comment-meta { flex: 1; min-width: 0; }
   .kv-admin-comment-author { font-weight: 600; color: var(--kv-text); font-size: .875rem; }
   .kv-admin-comment-sub { color: var(--kv-text-muted); font-size: .75rem; overflow-wrap: anywhere; }
   .kv-admin-comment-body { color: var(--kv-text); font-size: .875rem; white-space: pre-wrap; overflow-wrap: anywhere; }
   .kv-admin-comment-img { max-width: 200px; max-height: 120px; border-radius: 8px; margin-top: 6px; object-fit: cover; border: 1px solid var(--kv-border); }
   .kv-admin-comment-actions { display: flex; gap: 6px; flex-wrap: wrap; }
   .kv-admin-leader-list { display: flex; flex-direction: column; gap: 8px; }
   .kv-admin-leader-row { display: flex; align-items: center; gap: 12px; padding: 10px 12px; border: 1px solid var(--kv-border); border-radius: 10px; background: var(--kv-surface); }
   .kv-admin-leader-rank { font-weight: 700; color: var(--kv-accent); width: 28px; text-align: center; }
   .kv-admin-leader-cover { width: 40px; height: 56px; border-radius: 6px; overflow: hidden; flex: 0 0 40px; }
   .kv-admin-leader-cover img { width: 100%; height: 100%; object-fit: cover; }
   .kv-admin-leader-body { flex: 1; min-width: 0; }
   .kv-admin-leader-title { font-weight: 600; color: var(--kv-text); font-size: .875rem; }
   .kv-admin-leader-meta { color: var(--kv-text-muted); font-size: .75rem; }
   .kv-admin-leader-barwrap { height: 6px; background: var(--kv-surface-2); border-radius: 999px; margin-top: 6px; overflow: hidden; }
   .kv-admin-leader-bar { height: 100%; background: var(--kv-accent); border-radius: 999px; }
   .kv-admin-leader-views { font-weight: 700; color: var(--kv-text); font-size: .875rem; white-space: nowrap; }
   .kv-admin-leader-views span { color: var(--kv-text-muted); font-weight: 400; font-size: .7rem; }
   .kv-admin-leader-actions { display: flex; gap: 6px; flex-wrap: wrap; }

body.script:
//
(function () {
  'use strict';

  /* =========================================================================
     UBAH KONFIGURASI DI SINI SEBELUM MEMASANG DI BLOGGER
     CATATAN KEAMANAN: Jangan pernah menaruh secret OAuth atau token bot
     Telegram di dalam file XML ini. Gunakan environment Vercel.
     ========================================================================= */
  /* =========================================================================
     ARSITEKTUR & INTEGRASI (DOKUMENTASI - BACA SEBELUM DEPLOY)
     =========================================================================
     KOMPONEN:
     1. BLOGGER (frontend): file XML ini. Menayangkan SPA pembaca. Blogger TIDAK
        bisa menjalankan kode server - semua rahasia HARUS di environment Vercel.
     2. VERCEL FUNCTIONS (folder proyek: api/) menyimpan secrets:
         DATABASE_URL, TELEGRAM_BOT_TOKEN, TELEGRAM_STORAGE_CHAT_ID,
         TOKEN_SECRET, PUBLIC_API_URL, ALLOWED_ORIGINS,
         dan credential OAuth Google/Discord.
         Backend ini memakai Neon Postgres untuk katalog/akun/komentar,
         dan Telegram hanya untuk penyimpanan gambar.
        Pemetaan ke tema Blogger:
        - CONFIG.API_BASE_URL  = PUBLIC_API_URL  (origin Vercel yang sama)
        - return_to OAuth      = origin blog      (harus terdaftar di ALLOWED_ORIGINS)
        Endpoint minimum yang dipanggil frontend:
        - GET  /api/auth/{google|discord}/start dan /callback -> login OAuth
        - GET  /api/auth/me                -> profil dan role sesi aktif
        - GET  /api/catalog               -> { manga, chapters, comments }
        - POST /api/admin/upload-dual     -> simpan ke Telegram dan kembalikan
                                             URL proxy /api/media/{file_id}
        - POST /api/comment               -> { mangaId, content, ... }
        - POST /api/chapter/reaction      -> { chapterId, voterId, reaction }
        - POST /api/comment/upvote        -> { id, voterId }
        - POST /api/admin/save-manga      -> simpan/ubah data manga
        - POST /api/admin/save-chapter    -> simpan/ubah data chapter
        - POST /api/admin/delete-manga    -> { id }
        - POST /api/admin/delete-chapter  -> { id }
        - POST /api/admin/delete-comment  -> { id }
        - POST /api/admin/comment-status  -> { id, status }
        - POST /api/admin/pin-comment     -> { id } — sematkan komentar (admin)
        Semua endpoint admin memverifikasi header: Authorization: Bearer <token>.
     3. NEON POSTGRES menjadi database katalog/akun/komentar: archive
        disimpan sebagai dokumen JSONB pada tabel nexamanga_snapshot di
        database Neon (DATABASE_URL). Gambar tersimpan sebagai dokumen
        di chat Telegram; backend mem-proxy
        gambar lewat /api/media/{file_id}. Bot token dan connection string
        Neon tidak dikirim ke browser.
     BATASAN:
     - Snapshot disimpan sebagai dokumen JSONB di Neon (limit praktis 50 MiB),
        diperbarui dengan optimistic concurrency control (kolom version).
     - Tabel nexamanga_snapshot dibuat otomatis pada request pertama.
     - Gunakan satu sesi admin untuk mencegah perubahan serentak saling menimpa.
     - Upload JPEG/PNG/WebP maksimal 3 MiB per berkas (batas request Vercel).
     CATATAN JUJUR:
      - Tanpa API_BASE_URL (diisi = PUBLIC_API_URL), situs jalan mode lokal (localStorage).
     - Panduan deploy Vercel ada di README.md.
     - Notifikasi chapter baru butuh backend (mis. polling feed / bot
        broadcast ke channel) - tidak mungkin dari Blogger saja.
     - Akun lintas perangkat butuh backend; mode lokal menyimpan di browser.
     - Jangan unggah manga berhak cipta tanpa izin pemilik.
     ========================================================================= */
   var CONFIG = {
    SITE_NAME: 'NexaManga',                 /* UBAH: nama website Anda */
    SITE_TAGLINE: 'Platform baca manga berbahasa Indonesia cepat & nyaman.',
    /* Cara tercepat: edit langsung nilai API_BASE_URL di bawah ini (Tema > Edit HTML).
       Harus identik dengan PUBLIC_API_URL di .env / Vercel Environment Variables.
       Kosongkan hanya jika ingin mode lokal tanpa backend. */
    API_BASE_URL: 'https://nexamanga-nexamanga.vercel.app',
    DEFAULT_THEME: 'light', /* 'dark' atau 'light' */
    ITEMS_PER_PAGE: 8,
    CONTACT_EMAIL: 'redaksi@nexamanga.example' /* UBAH: email redaksi */
  };

  /* =========================================================================
     DATA CONTOH LEGAL (FALLBACK JIKA API_BASE_URL BELUM DIHUBUNGKAN)
     ========================================================================= */
   var SAMPLE_DATA = { manga: [], chapters: [], comments: [] };

  /* =========================================================================
     STATE & PERSISTENSI LOKAL
     ========================================================================= */
  var state = {
    route: 'home',
    params: {},
    theme: localStorage.getItem('kv_theme') || CONFIG.DEFAULT_THEME,
    /* Data dimuat dari: backend API -> data lokal admin -> data contoh */
     data: JSON.parse(localStorage.getItem('kv_local_data') || 'null') || { manga: [], chapters: [], comments: [] },
    loading: false,
    error: null,
    search: '',
    filterGenres: [],
    filterStatus: 'Semua',
    filterType: 'Semua',
    sortBy: 'terbaru',
    openCatalogDropdown: null,
    page: 1,
     chapterSortAsc: false,
     chapterSearch: '',
    readerMode: 'vertical', // 'vertical' | 'paged'
    readerWidth: 760,
    readerTheme: 'dark',
    readerDir: 'ltr', // 'ltr' | 'rtl'
    currentPageIdx: 0,
     readerMenuOpen: false,
     readerChapterSearch: '',
     readerChapterSearchRefocus: false,

    readerSettingsOpen: false,
     autoScroll: false,
     autoScrollSpeed: 2.5,

    readerDockTimer: null,
    user: null,
    bookmarks: JSON.parse(localStorage.getItem('kv_bookmarks') || '[]'),
    history: JSON.parse(localStorage.getItem('kv_history') || '[]'),
    adminToken: localStorage.getItem('kv_session_token') || '',
    mobileMenuOpen: false,
    refocusSearch: false,
    /* --- State panel admin & moderasi --- */
    adminTab: 'dashboard',
    adminForm: null,            // form manga aktif (objek) atau null = daftar
    adminChapterForm: null,     // form chapter aktif (objek) atau null
     adminChapterMangaId: '',
     adminChapterFullId: null,

    adminSearch: '',
    adminRefocusSearch: false,
     adminExpandedManga: null,
     uploadProgress: null,
     analyticsData: undefined,

     commentFilter: 'Semua',
     commentSort: 'newest',

    commentNotice: '',
     pendingDelete: null,        // { type, id, label, confirmLabel }
     toasts: [],
      usersCache: undefined,
      adminDrawerOpen: false,
      editingProfile: false,
      replyingTo: null,
      imageTargetForm: null,
      commentImageIndex: 0,
      commentImageMap: {},
      viewedChapters: {}
    };

  /* Persistensi lokal: perubahan admin disimpan ke localStorage agar
     tidak hilang saat reload (mode demo tanpa backend). */
  function persistData() {
    try { localStorage.setItem('kv_local_data', JSON.stringify(state.data)); } catch (e) { /* kuota penuh */ }
  }

  function uid(prefix) {
    return prefix + '-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 7);
  }

  function slugify(text) {
    return String(text || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  }

  function today() {
    return new Date().toISOString().slice(0, 10);
  }

   function siteSetting(key, fallback) {
     var settings = (state.data && state.data.settings) ? state.data.settings : {};
     var local = {};
     try { local = JSON.parse(localStorage.getItem('kv_site_settings') || '{}') || {}; } catch (e) { local = {}; }
     if (settings && settings[key]) return settings[key];
     if (local && local[key]) return local[key];
     return fallback;
   }

   function siteName() { return siteSetting('siteName', CONFIG.SITE_NAME); }
   function siteTagline() { return siteSetting('siteTagline', CONFIG.SITE_TAGLINE); }
   function siteLogo() { return siteSetting('logoUrl', ''); }
   function siteContact() { return siteSetting('contactEmail', CONFIG.CONTACT_EMAIL); }
   function brandMode() { return siteSetting('brandMode', 'logo-name'); }
   function siteNameColor() { return siteSetting('siteNameColor', ''); }
   function siteNameStyle() { var c = siteNameColor(); return c ? ' style="color:' + escapeHtml(c) + '"' : ''; }
   function renderBrandInner(textClass) {
     var mode = brandMode(), logo = siteLogo(), name = siteName();
     var html = '';
     if (mode !== 'name-only') {
       html += logo ? '<span class="kv-brand-logo"><img src="' + escapeHtml(logo) + '" alt="Logo ' + escapeHtml(name) + '"/></span>' : '<span class="kv-brand-mark" aria-hidden="true">N</span>';
     }
     if (mode !== 'logo-only') {
       html += '<span' + (textClass ? ' class="' + escapeHtml(textClass) + '"' : '') + siteNameStyle() + '>' + escapeHtml(name) + '</span>';
     }
     return html;
   }
   function renderBrandMarkup(extraClass) {
     var logo = siteLogo();
     if (logo) return '<span class="kv-brand-logo ' + (extraClass || '') + '"><img src="' + escapeHtml(logo) + '" alt="Logo ' + escapeHtml(siteName()) + '"/></span>';
     return '<span class="kv-brand-mark" aria-hidden="true">N</span>';
   }

    function mangaById(id) {
     return state.data.manga.filter(function (m) { return m.id === id; })[0] || null;
   }

    function voterId() {
      var id = localStorage.getItem('kv_voter_id');
      if (!id) { id = 'v-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8); localStorage.setItem('kv_voter_id', id); }
      return id;
    }

    function purgeLegacyProfileOverrides() {
      try {
        if (localStorage.getItem('kv_pov_purged') === '2') return;
        var doomed = [];
        for (var i = 0; i < localStorage.length; i++) {
          var key = localStorage.key(i);
          if (!key) continue;
          var isLegacyGlobal = key === 'kv_profile_override';
          var isOldPerUser = key.indexOf('kv_profile_override_') === 0 && key.indexOf('kv_profile_override_v2_') !== 0;
          if (isLegacyGlobal || isOldPerUser) doomed.push(key);
        }
        doomed.forEach(function (key) { localStorage.removeItem(key); });
        localStorage.setItem('kv_pov_purged', '2');
      } catch (e) { /* abaikan */ }
    }

    function profileOverride() {
      var id = state.user && state.user.id;
      if (!id) return {};
      try { return JSON.parse(localStorage.getItem('kv_profile_override_v2_' + id) || '{}') || {}; } catch (e) { return {}; }
    }

    function currentDisplayName(fallback) {
      var o = profileOverride();
      return o.name || (state.user && state.user.name) || fallback || 'Pengguna';
    }

    function currentDisplayAvatar(fallback) {
      var o = profileOverride();
      if (o.avatar) return o.avatar;
      if (state.user && state.user.avatar) return state.user.avatar;
      return fallback || null;
    }

    function replaceImageTokens(content) {
      var map = state.commentImageMap || {};
      Object.keys(map).forEach(function (token) {
        var url = map[token];
        var md = '![gambar](' + url + ')';
        content = content.split(token).join(md);
      });
      state.commentImageMap = {};
      return content;
    }

   function chapterReactionSummary(chapterId) {
     var all = (state.data && state.data.reactions) || {};
     var forChapter = (all[chapterId] && typeof all[chapterId] === 'object' && !Array.isArray(all[chapterId])) ? all[chapterId] : {};
     var keys = ['fire', 'shock', 'cry', 'laugh', 'angry'];
     var key = state.user ? state.user.id : voterId();
     var counts = {};
     var userVote = null;
     for (var i = 0; i < keys.length; i++) {
       var list = Array.isArray(forChapter[keys[i]]) ? forChapter[keys[i]] : [];
       counts[keys[i]] = list.length;
       if (list.indexOf(key) !== -1) userVote = keys[i];
     }
     return { counts: counts, userVote: userVote };
   }

   function chapterReactionLocal(chapterId, reaction) {
     var keys = ['fire', 'shock', 'cry', 'laugh', 'angry'];
     if (keys.indexOf(reaction) === -1) return;
     if (!state.data.reactions || typeof state.data.reactions !== 'object' || Array.isArray(state.data.reactions)) {
       state.data.reactions = {};
     }
     var forChapter = state.data.reactions[chapterId];
     if (!forChapter || typeof forChapter !== 'object' || Array.isArray(forChapter)) forChapter = {};
     for (var i = 0; i < keys.length; i++) {
       if (!Array.isArray(forChapter[keys[i]])) forChapter[keys[i]] = [];
     }
     var key = state.user ? state.user.id : voterId();
     var removeOnly = false;
     for (var j = 0; j < keys.length; j++) {
       var idx = forChapter[keys[j]].indexOf(key);
       if (idx !== -1) {
         forChapter[keys[j]].splice(idx, 1);
         if (keys[j] === reaction) removeOnly = true;
       }
     }
     if (!removeOnly) forChapter[reaction].push(key);
     state.data.reactions[chapterId] = forChapter;
     persistData();
     if (CONFIG.API_BASE_URL) {
       fetch(CONFIG.API_BASE_URL + '/api/chapter/reaction', {
         method: 'POST',
         headers: { 'Content-Type': 'application/json' },
         body: JSON.stringify({ chapterId: chapterId, voterId: key, reaction: reaction })
       }).then(function (r) { return r.ok ? r.json() : null; }).then(function () { render(); }).catch(function () {});
     }
     render();
   }

   function aggregateChapterReactions(manga) {
     var keys = ['fire', 'shock', 'cry', 'laugh', 'angry'];
     var counts = {};
     for (var i = 0; i < keys.length; i++) counts[keys[i]] = 0;
     var chapterIds = state.data.chapters.filter(function (c) { return c.mangaId === manga.id; }).map(function (c) { return c.id; });
     var all = (state.data && state.data.reactions) || {};
     for (var i = 0; i < chapterIds.length; i++) {
       var forChapter = all[chapterIds[i]];
       if (!forChapter || typeof forChapter !== 'object' || Array.isArray(forChapter)) continue;
       for (var j = 0; j < keys.length; j++) {
         if (Array.isArray(forChapter[keys[j]])) counts[keys[j]] += forChapter[keys[j]].length;
       }
     }
     return { counts: counts, userVote: null };
   }

   function adminPinComment(id) {
     var comment = state.data.comments.filter(function (x) { return x.id === id; })[0];
     if (!comment) return;
     comment.pinned = !comment.pinned;
     persistData();
     render();
     if (CONFIG.API_BASE_URL) {
       fetch(CONFIG.API_BASE_URL + '/api/admin/pin-comment', {
         method: 'POST',
         headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
         body: JSON.stringify({ id: id })
       }).then(function (r) { return r.ok ? r.json() : null; }).then(function (res) {
         if (res && typeof res.pinned === 'boolean' && comment) comment.pinned = res.pinned;
         render();
       }).catch(function () {
         comment.pinned = !comment.pinned;
         render();
         toast('Gagal mengubah pin komentar.', 'warn');
       });
     }
   }

   function upvoteCommentLocal(id) {
     var c = state.data.comments.filter(function (x) { return x.id === id; })[0];
     if (!c) return;
     if (!Array.isArray(c.upvotes)) c.upvotes = [];
     var key = state.user ? state.user.id : voterId();
     var idx = c.upvotes.indexOf(key);
     if (idx === -1) c.upvotes.push(key); else c.upvotes.splice(idx, 1);
     persistData();
     if (CONFIG.API_BASE_URL) {
       fetch(CONFIG.API_BASE_URL + '/api/comment/upvote', {
         method: 'POST',
         headers: { 'Content-Type': 'application/json' },
         body: JSON.stringify({ id: id, voterId: key })
       }).then(function (r) { return r.ok ? r.json() : null; }).then(function (res) {
         if (res && res.comment && Array.isArray(res.comment.upvotes)) {
           c.upvotes = res.comment.upvotes;
           render();
         }
       }).catch(function () {});
     }
     render();
   }

  function chapterById(id) {
    return state.data.chapters.filter(function (c) { return c.id === id; })[0] || null;
  }

  var readerAutoTimer = null;

  function stopAutoScroll() {
    if (readerAutoTimer) {
      clearInterval(readerAutoTimer);
      readerAutoTimer = null;
    }
    state.autoScroll = false;
  }

  function toggleAutoScroll() {
    if (readerAutoTimer) {
      stopAutoScroll();
      render();
      return;
    }
    state.autoScroll = true;
    readerAutoTimer = setInterval(function () {
      var doc = document.documentElement;
      var remaining = doc.scrollHeight - window.innerHeight - doc.scrollTop;
      if (remaining <= 16) {
        stopAutoScroll();
        render();
        return;
      }
       window.scrollBy(0, state.autoScrollSpeed || 2.5);

    }, 16);
    render();
  }

  /* Sinkronisasi ke Vercel (hanya jika API_BASE_URL aktif) */
  var apiSyncQueue = Promise.resolve();
  function apiSync(path, payload) {
    if (!CONFIG.API_BASE_URL) return;
    apiSyncQueue = apiSyncQueue.then(function () {
      return fetch(CONFIG.API_BASE_URL + path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
        body: JSON.stringify(payload)
      }).then(function (res) {
        if (!res.ok) throw new Error('HTTP ' + res.status);
      });
    }).catch(function (err) {
      toast('Tersimpan lokal, tetapi gagal sinkron ke server (' + path + '): ' + err.message, 'warn');
    });
  }

  /* Notifikasi toast (tidak ikut terhapus saat render ulang: diluar #kv-app) */
  function toast(msg, type) {
    var wrap = document.getElementById('kv-toasts');
    if (!wrap) {
      wrap = document.createElement('div');
      wrap.id = 'kv-toasts';
      wrap.className = 'kv-toasts';
      wrap.setAttribute('role', 'status');
      wrap.setAttribute('aria-live', 'polite');
      document.body.appendChild(wrap);
    }
    var t = document.createElement('div');
    t.className = 'kv-toast' + (type ? ' kv-toast-' + type : '');
    t.textContent = msg;
    wrap.appendChild(t);
    setTimeout(function () { if (t.parentNode) t.parentNode.removeChild(t); }, 4000);
  }

  function confirmDelete(type, id, label, confirmLabel) {
    state.pendingDelete = { type: type, id: id, label: label, confirmLabel: confirmLabel || 'Hapus' };
    render();
  }

  /* Ikon SVG inline (stroke currentColor) untuk menu & tombol console admin */
  function kvIcon(name) {
    var p = {
      grid: '<path d="M3 3h7v7H3z"/><path d="M14 3h7v7h-7z"/><path d="M3 14h7v7H3z"/><path d="M14 14h7v7h-7z"/>',
      book: '<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>',
      layers: '<path d="m12 2 10 6-10 6L2 8l10-6z"/><path d="m2 14 10 6 10-6"/>',
      chat: '<path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>',
      gear: '<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09a1.65 1.65 0 0 0-1-1.51 1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09a1.65 1.65 0 0 0 1.51-1 1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33h.01a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51h.01a1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82v.01a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>',
      plus: '<path d="M12 5v14"/><path d="M5 12h14"/>',
      out: '<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5"/><path d="M21 12H9"/>',
      globe: '<circle cx="12" cy="12" r="10"/><path d="M2 12h20"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>',
      eye: '<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/>',
      users: '<path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',
      trend: '<path d="m23 6-9.5 9.5-5-5L1 18"/><path d="M17 6h6v6"/>',
      zap: '<path d="M13 2 3 14h9l-1 8 10-12h-9l1-8z"/>',
      chev: '<path d="m6 9 6 6 6-6"/>',
      search: '<circle cx="11" cy="11" r="7"/><path d="m21 21-4-4"/>',
      share: '<path d="M12 16V4"/><path d="m8 8 4-4 4 4"/><path d="M4 13v6a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-6"/>'
    };
    return '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + (p[name] || '') + '</svg>';
  }

  /* Chip pill gaya SaaS untuk meta informasi */
  function kvChip(text, accent, mono) {
    return '<span class="kv-chip' + (accent ? ' kv-chip-accent' : '') + (mono ? ' kv-mono' : '') + '">' + escapeHtml(text) + '</span>';
  }

  function applyTheme() {
    if (state.theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('kv_theme', state.theme);
    var metaTheme = document.querySelector('meta[name="theme-color"]');
    if (metaTheme) metaTheme.setAttribute('content', state.theme === 'dark' ? '#0B0E17' : '#F5F7FB');
  }

  function escapeHtml(str) {
    return String(str || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function kvSpoilerIcon() {
    return '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8S1 12 1 12z"/><circle cx="12" cy="12" r="3"/></svg>';
  }

  function renderCommentContent(text) {
    var html = escapeHtml(text);
    html = html.replace(/!\[([^\]]*)\]\((https?:\/\/[^\s)]+)\)/g, function (m, alt, url) {
      return '<img class="kv-comment-image" src="' + escapeHtml(url) + '" alt="' + escapeHtml(alt || 'Gambar komentar') + '" loading="lazy" referrerpolicy="no-referrer"/>';
    });
    html = html.replace(/\|\|([\s\S]+?)\|\|/g, function (m, inner) {
      return '<div class="kv-spoiler"><button type="button" class="kv-spoiler-toggle">' + kvSpoilerIcon() + '<span class="kv-spoiler-label">Spoiler</span><span class="kv-spoiler-state kv-spoiler-state-open">Buka</span><span class="kv-spoiler-state kv-spoiler-state-close">Tutup</span></button><div class="kv-spoiler-body">' + inner + '</div></div>';
    });
    html = html.replace(/\*\*([\s\S]+?)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/\*([\s\S]+?)\*/g, '<em>$1</em>');
    return html;
  }

  function svgFallbackCover(title) {
    var safe = escapeHtml(title || 'Manga');
    return '<div style="width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:16px;text-align:center;background:linear-gradient(145deg,#111827,#1e1b4b);color:#e2e8f0;">' +
      '<div style="font-size:0.75rem;opacity:0.7;margin-bottom:6px;">SAMPUL CONTOH</div>' +
      '<div style="font-weight:700;font-size:0.95rem;">' + safe + '</div>' +
    '</div>';
  }

  function renderCover(url, title) {
    if (!url || url.indexOf('SamplePlaceholder') !== -1) {
      return svgFallbackCover(title);
    }
    return '<img src="' + escapeHtml(url) + '" alt="Sampul ' + escapeHtml(title) + '" loading="lazy" referrerpolicy="no-referrer" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\';"/>' +
      '<div style="display:none;width:100%;height:100%;align-items:center;justify-content:center;padding:16px;text-align:center;background:#111827;color:#cbd5e1;">' + escapeHtml(title) + '</div>';
  }

  function parseRoute() {
    var legacyRoute = window.location.hash.indexOf('#/') === 0 ? window.location.hash.slice(1) : '';
    var routePath = legacyRoute || window.location.pathname;
    if (!routePath || routePath === '/') routePath = '/';
    if (routePath.charAt(0) !== '/') routePath = '/' + routePath;

    var query = window.location.search.replace(/^\?/, '').split('&').filter(function (part) {
      var pair = part.split('=');
      return part && !(pair[0] === 'm' && pair[1] === '1');
    }).join('&');
    var cleanUrl = legacyRoute
      ? window.location.pathname + (query ? '?' + query : '') + '#' + routePath
      : routePath + (query ? '?' + query : '');
    if (window.location.pathname + window.location.search + window.location.hash !== cleanUrl) {
      window.history.replaceState(null, '', cleanUrl);
    }

    var parts = routePath.split('/').filter(Boolean);
    if (parts.length === 0) { state.route = 'home'; state.params = {}; return; }
    if (parts[0] === 'archive') { state.route = 'catalog'; state.params = {}; return; }
    if (parts[0] === 'manga' && parts[1]) { state.route = 'detail'; state.params = { slug: parts[1] }; return; }
    if (parts[0] === 'baca' && parts[1] && parts[2]) { state.route = 'reader'; state.params = { slug: parts[1], chapterId: parts[2] }; state.currentPageIdx = 0; return; }
    if (parts[0] === 'akun') { state.route = 'account'; state.params = {}; return; }
    if (parts[0] === 'admin') { state.route = 'admin'; state.params = {}; return; }
    if (['tentang', 'kontak', 'privasi', 'ketentuan'].indexOf(parts[0]) !== -1) {
      state.route = 'info'; state.params = { page: parts[0] }; return;
    }
    state.route = '404'; state.params = {};
  }

   function trackPageview() {
     if (!CONFIG.API_BASE_URL) return;
     try {
       var vid = localStorage.getItem('kv_visitor_id');
       if (!vid) { vid = 'v-' + Math.random().toString(36).slice(2) + Date.now().toString(36); localStorage.setItem('kv_visitor_id', vid); }
       fetch(CONFIG.API_BASE_URL + '/api/track', {
         method: 'POST',
         headers: { 'Content-Type': 'application/json' },
         body: JSON.stringify({ visitorId: vid })
       }).catch(function () {});
     } catch (e) {}
   }

   function navigate(path) {
     var routePath = String(path || '/').replace(/^#/, '');
     if (routePath.charAt(0) !== '/') routePath = '/' + routePath;
     var routeHash = '#' + routePath;
     if (window.location.hash !== routeHash) {
       window.history.pushState(null, '', routeHash);
     }
     state.mobileMenuOpen = false;
     state.commentNotice = null;
     parseRoute();
     render();
     window.scrollTo(0, 0);
     trackPageview();
   }


  function syncFromApi() {
    if (!CONFIG.API_BASE_URL) return;
    state.loading = true;
    render();
    var headers = {};
    if (state.adminToken) headers.Authorization = 'Bearer ' + state.adminToken;
    fetch(CONFIG.API_BASE_URL + '/api/catalog', { headers: headers })
      .then(function (r) {
        if (r.status === 409) throw new Error('Database belum diinisialisasi. Login sebagai admin (Google/Discord) sekali untuk memulai.');
        if (!r.ok) throw new Error('Gagal memuat archive dari server proxy (HTTP ' + r.status + ').');
        return r.json();
      })
      .then(function (json) {
        state.data = json;
        state.loading = false;
        state.error = null;
        render();
      })
      .catch(function (err) {
        state.loading = false;
        state.error = err.message;
        render();
      });
  }

  function initializeAuth() {
    purgeLegacyProfileOverrides();
    sessionStorage.removeItem('kv_admin_token');
     var callbackToken = new URLSearchParams(window.location.search).get('auth_token');
     if (callbackToken) {
       state.adminToken = callbackToken;
       localStorage.setItem('kv_session_token', callbackToken);
       localStorage.removeItem('kv_local_data');
       window.history.replaceState(null, '', window.location.pathname + window.location.hash);
     }
     if (!state.adminToken || !CONFIG.API_BASE_URL) {
       state.user = null;
       render();
       syncFromApi();
       return;
     }
     render();
     (function claimAdminIfNeeded() {
       return fetch(CONFIG.API_BASE_URL + '/api/auth/claim-admin', {
         method: 'POST',
         headers: { Authorization: 'Bearer ' + state.adminToken }
       }).then(function (response) {
         if (!response.ok) return null;
         return response.json();
       }).then(function (result) {
         if (result && result.token) {
           state.adminToken = result.token;
            localStorage.setItem('kv_session_token', result.token);
         }
       }).catch(function () {});
     })().then(function () {
       fetch(CONFIG.API_BASE_URL + '/api/auth/me', {
         headers: { Authorization: 'Bearer ' + state.adminToken }
       }).then(function (response) {
         if (!response.ok) throw new Error('Sesi tidak valid.');
         return response.json();
        }).then(function (result) {
          state.user = result.user || null;
          if (state.user && result.role) state.user.role = result.role;
        }).catch(function () {
         state.adminToken = '';
         state.user = null;
         localStorage.removeItem('kv_session_token');
       }).then(function () {
         render();
         syncFromApi();
       });
     });
  }

  function collectGenres() {
    var out = [];
    state.data.manga.forEach(function (m) { (m.genres || []).forEach(function (g) { if (out.indexOf(g) === -1) out.push(g); }); });
    return out;
  }

  function collectTypes() {
    var out = [];
    state.data.manga.forEach(function (m) { if (m.type && out.indexOf(m.type) === -1) out.push(m.type); });
    return out;
  }

  function latestChapterOf(m) {
    var chs = state.data.chapters.filter(function (c) { return c.mangaId === m.id; });
    return chs.sort(function (a, b) { return b.number - a.number; })[0];
  }

  function renderLightCard(m) {
    var latest = latestChapterOf(m);
    var rating = Number(m.rating || 0).toFixed(1);
    return '<a class="kv-home-card" href="#/manga/' + escapeHtml(m.slug) + '" aria-label="Buka ' + escapeHtml(m.title) + '">' +
      '<div class="kv-home-card-cover">' + renderCover(m.coverBloggerUrl, m.title) +
        (latest ? '<span class="kv-home-card-badge">Ch. ' + escapeHtml(latest.number) + '</span>' : '') +
      '</div>' +
      '<div class="kv-home-card-tags"><span class="kv-home-card-tag">' + escapeHtml(m.type || 'Manga') + '</span><span class="kv-home-card-tag status">' + escapeHtml(m.status || 'Ongoing') + '</span></div>' +
      '<h3 class="kv-home-card-title">' + escapeHtml(m.title) + '</h3>' +
      '<div style="margin-top:auto;padding-top:10px;display:flex;justify-content:flex-end;align-items:center;"><span style="font-size:.7rem;font-weight:700;color:#f59e0b;">&#9733; ' + escapeHtml(rating) + '</span></div>' +
    '</a>';
  }

  /* =========================================================================
     RENDER HEADER & FOOTER
     ========================================================================= */
  function renderHeader() {
    if (state.route === 'admin' || state.route === 'reader') return '';
     var navItems = [
       { path: '/', label: 'Beranda', key: 'home' },
       { path: '/archive', label: 'Archive', key: 'catalog' },
       { path: '/akun', label: state.user ? 'Akun Saya' : 'Masuk', key: 'account' },
       { path: '/tentang', label: 'Tentang', key: 'info' }
     ];
     if (state.user && state.user.role === 'admin') navItems.splice(3, 0, { path: '/admin', label: 'Admin', key: 'admin' });
    var linksHtml = navItems.map(function (item) {
      var cls = 'kv-nav-link' + (item.key === 'account' ? ' kv-nav-login' : '') + (state.route === item.key ? ' active' : '');
      return '<a class="' + cls + '" href="' + item.path + '"' + (state.route === item.key ? ' aria-current="page"' : '') + '>' + item.label + '</a>';
    }).join('');
    var themeLabel = state.theme === 'dark' ? 'Aktifkan mode terang' : 'Aktifkan mode gelap';
    var themeIcon = state.theme === 'dark'
      ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/></svg>'
      : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13z"/></svg>';

    return '<header class="kv-header">' +
      '<div class="kv-container kv-header-inner">' +
        '<a class="kv-brand" href="#/" aria-label="' + escapeHtml(siteName()) + ' - beranda">' +
          renderBrandInner() +
        '</a>' +
        '<nav class="kv-nav" aria-label="Navigasi Utama">' + linksHtml + '</nav>' +
        '<div class="kv-header-actions">' +
          '<button type="button" class="kv-btn kv-btn-ghost kv-theme-toggle" data-action="toggle-theme" aria-label="' + themeLabel + '" title="' + themeLabel + '">' + themeIcon + '</button>' +
          '<button type="button" class="kv-btn kv-btn-ghost kv-mobile-btn" data-action="toggle-mobile-menu" aria-label="' + (state.mobileMenuOpen ? 'Tutup menu navigasi' : 'Buka menu navigasi') + '" aria-expanded="' + (state.mobileMenuOpen ? 'true' : 'false') + '" aria-controls="kv-mobile-menu">' + (state.mobileMenuOpen ? '&times;' : '<span aria-hidden="true">&#9776;</span>') + '</button>' +
        '</div>' +
      '</div>' +
      (state.mobileMenuOpen ? '<nav id="kv-mobile-menu" class="kv-container kv-mobile-menu" aria-label="Navigasi mobile">' + linksHtml + '</nav>' : '') +
    '</header>';
  }

  function renderFooter() {
    if (state.route === 'reader' || state.route === 'admin') return '';
    return '<footer class="kv-footer">' +
      '<div class="kv-container kv-footer-inner">' +
        '<div><strong' + siteNameStyle() + '>' + escapeHtml(siteName()) + '</strong> &middot; ' + escapeHtml(siteTagline()) + '</div>' +
        '<div style="display:flex;flex-wrap:wrap;gap:16px;align-items:center;">' +
          '<a href="#/tentang">Tentang</a>' +
          '<a href="#/kontak">Kontak</a>' +
          '<a href="#/privasi">Kebijakan Privasi</a>' +
          '<a href="#/ketentuan">Ketentuan</a>' +
        '</div>' +
      '</div>' +
    '</footer>';
  }

  /* =========================================================================
     HALAMAN BERANDA
     ========================================================================= */
  function renderHome() {
    var featured = state.data.manga.filter(function (m) { return m.featured; })[0] || state.data.manga[0];
    if (!featured) return '<div class="kv-container kv-section"><p>Belum ada manga tersedia.</p></div>';

    var featuredChapters = state.data.chapters.filter(function (c) { return c.mangaId === featured.id; });
    var chCount = featuredChapters.length;
    var featuredRating = Number(featured.rating || 0).toFixed(1);
    var featuredViews = (featured.views || 0).toLocaleString('id-ID');

    function latestChapter(m) {
      var chs = state.data.chapters.filter(function (c) { return c.mangaId === m.id; });
      return chs.sort(function (a, b) { return b.number - a.number; })[0];
    }
    function homeCard(m) {
      var latest = latestChapter(m);
      var rating = Number(m.rating || 0).toFixed(1);
      return '<a class="kv-home-card" href="#/manga/' + escapeHtml(m.slug) + '" aria-label="Buka ' + escapeHtml(m.title) + '">' +
        '<div class="kv-home-card-cover">' + renderCover(m.coverBloggerUrl, m.title) +
          (latest ? '<span class="kv-home-card-badge">Ch. ' + escapeHtml(latest.number) + '</span>' : '') +
        '</div>' +
        '<div class="kv-home-card-tags"><span class="kv-home-card-tag">' + escapeHtml(m.type || 'Manga') + '</span><span class="kv-home-card-tag status">' + escapeHtml(m.status || 'Ongoing') + '</span></div>' +
        '<h3 class="kv-home-card-title">' + escapeHtml(m.title) + '</h3>' +
        '<div style="margin-top:auto;padding-top:10px;display:flex;justify-content:flex-end;align-items:center;"><span style="font-size:.7rem;font-weight:700;color:#f59e0b;">&#9733; ' + escapeHtml(rating) + '</span></div>' +
      '</a>';
    }
    function rankingCard(m, idx) {
      var latest = latestChapter(m);
      var rating = Number(m.rating || 0).toFixed(2);
      return '<a class="kv-home-rank" href="#/manga/' + escapeHtml(m.slug) + '" aria-label="Buka ' + escapeHtml(m.title) + '">' +
        '<div class="kv-home-rank-cover"><img src="' + escapeHtml(m.coverBloggerUrl || '') + '" alt="' + escapeHtml(m.title) + '" loading="lazy" referrerpolicy="no-referrer"/><div class="kv-home-rank-num">' + (idx + 1) + '</div></div>' +
        '<div style="flex:1;min-width:0;">' +
          '<div style="display:flex;gap:6px;align-items:center;margin-bottom:4px;"><span class="kv-home-card-tag">' + escapeHtml(m.type || 'Manga') + '</span><span style="font-size:.72rem;font-weight:700;color:#f59e0b;">&#9733; ' + escapeHtml(rating) + '</span></div>' +
          '<h4 class="kv-home-rank-title">' + escapeHtml(m.title) + '</h4>' +
          '<p class="kv-home-rank-meta">' + (latest ? 'Chapter ' + escapeHtml(latest.number) + ' &middot; ' : '') + escapeHtml((m.views || 0).toLocaleString('id-ID')) + ' Views</p>' +
          '<div class="kv-home-rank-stat">Trending di ' + escapeHtml(siteName()) + '</div>' +
        '</div>' +
      '</a>';
    }

     var latestCards = state.data.manga.slice()
       .map(function (m) {
         var chs = state.data.chapters.filter(function (c) { return c.mangaId === m.id; });
         var last = m.updatedAt || '';
         chs.forEach(function (c) { if (String(c.publishedAt || '') > String(last)) last = c.publishedAt; });
         return { m: m, last: last };
       })
       .filter(function (x) { return x.last; })
       .sort(function (a, b) { return String(b.last).localeCompare(String(a.last)); })
       .slice(0, 6)
       .map(function (x) { return homeCard(x.m); })
       .join('');

    var genres = ['Semua Koleksi'].concat(collectGenres().slice(0, 9));
    var popular = state.data.manga.slice().sort(function (a, b) { return (b.views || 0) - (a.views || 0); }).slice(0, 3);
    var recommended = state.data.manga.filter(function (m) { return m.recommended; });
    var curated = (recommended.length ? recommended : popular).slice(0, 2).map(function (m) {
      var rating = Number(m.rating || 0).toFixed(1);
      return '<a class="kv-home-curated-card" href="#/manga/' + escapeHtml(m.slug) + '" aria-label="Buka ' + escapeHtml(m.title) + '">' +
        '<div class="kv-home-curated-cover"><img src="' + escapeHtml(m.coverBloggerUrl || '') + '" alt="' + escapeHtml(m.title) + '" loading="lazy" referrerpolicy="no-referrer"/></div>' +
        '<div style="flex:1;min-width:0;display:flex;flex-direction:column;">' +
          '<span class="kv-home-curated-tag">Staff Pick</span>' +
          '<h3 class="kv-home-curated-title">' + escapeHtml(m.title) + '</h3>' +
          '<p class="kv-home-curated-desc">' + escapeHtml(m.synopsis) + '</p>' +
          '<div class="kv-home-curated-foot"><span class="kv-home-curated-link">Baca Bab Pertama &rarr;</span><span>&#9733; ' + escapeHtml(rating) + '</span></div>' +
        '</div>' +
      '</a>';
    }).join('');

    var bannerItems = state.data.manga.slice().sort(function (a, b) {
      var af = a.featured ? 1 : 0;
      var bf = b.featured ? 1 : 0;
      if (af !== bf) return bf - af;
      return String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')) || String(a.title || '').localeCompare(String(b.title || ''));
    }).slice(0, 8);
    var bannerCards = bannerItems.map(function (m) {
      var latest = latestChapter(m);
      var rating = Number(m.rating || 0).toFixed(1);
      var chCount = state.data.chapters.filter(function (c) { return c.mangaId === m.id; }).length;
      var views = (m.views || 0).toLocaleString('id-ID');
      return '<a class="kv-home-banner-card" href="#/manga/' + escapeHtml(m.slug) + '" aria-label="Buka ' + escapeHtml(m.title) + '">' +
        (m.coverBloggerUrl
          ? '<img class="kv-home-banner-img" src="' + escapeHtml(m.coverBloggerUrl) + '" alt="" aria-hidden="true" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display=\'none\';"/>'
          : '<div class="kv-home-banner-img kv-home-banner-img-empty"></div>') +
        '<div class="kv-home-banner-overlay"></div>' +
        '<div class="kv-home-banner-body">' +
          '<h2 class="kv-home-banner-title">' + escapeHtml(m.title) + '</h2>' +
          '<div class="kv-home-banner-meta"><span>&#9733; ' + escapeHtml(rating) + '</span><span>' + (chCount || 0) + ' chapter</span><span>' + escapeHtml(views) + ' dibaca</span></div>' +
          '<span class="kv-home-banner-cta">Baca Sekarang &rarr;</span>' +
        '</div>' +
        (m.coverBloggerUrl
          ? '<img class="kv-home-banner-poster" src="' + escapeHtml(m.coverBloggerUrl) + '" alt="Sampul ' + escapeHtml(m.title) + '" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display=\'none\';"/>'
          : '<div class="kv-home-banner-poster kv-home-banner-poster-empty"><span>Sampul</span></div>') +
      '</a>';
    }).join('');
    var bannerMiddleIndex = Math.floor(bannerItems.length / 2);
    var bannerDots = bannerItems.map(function (m, index) {
      var active = index === bannerMiddleIndex;
      return '<button type="button" class="kv-home-banner-dot' + (active ? ' is-active' : '') + '" data-action="scroll-banner-dot" data-index="' + index + '" role="tab" aria-selected="' + (active ? 'true' : 'false') + '" aria-label="Banner ' + (index + 1) + ': ' + escapeHtml(m.title) + '"></button>';
    }).join('');
    return '<main class="kv-container kv-home-light">' +
      '<section class="kv-home-banner" aria-label="Manga Sorotan">' +
        '<div class="kv-home-banner-track" id="kv-banner-track" tabindex="0" role="region" aria-label="Banner manga yang bisa digeser">' +
          bannerCards +
        '</div>' +
        '<div class="kv-home-banner-dots" id="kv-banner-dots" role="tablist" aria-label="Pilih banner">' +
          bannerDots +
        '</div>' +
      '</section>' +
      '<div class="kv-home-genres" aria-label="Kategori populer">' +
        genres.map(function (g, i) {
          return '<button type="button" class="kv-home-genre' + (i === 0 ? ' active' : '') + '" data-action="quick-genre" data-genre="' + escapeHtml(g) + '">' + escapeHtml(g) + '</button>';
        }).join('') +
      '</div>' +
      '<section class="kv-home-section" aria-labelledby="heading-updates">' +
        '<div class="kv-home-section-head">' +
          '<div><h2 class="kv-home-section-title" id="heading-updates">Update Terbaru</h2></div>' +
          '<a class="kv-home-link" href="#/archive">Lihat Semua &rarr;</a>' +
        '</div>' +
        '<div class="kv-home-grid">' + latestCards + '</div>' +
      '</section>' +
      '<section class="kv-home-section" aria-labelledby="heading-popular">' +
        '<div class="kv-home-section-head">' +
          '<div><h2 class="kv-home-section-title" id="heading-popular">Komik Populer &amp; Trending</h2></div>' +
          '<a class="kv-home-link" href="#/archive">Lihat Semua &rarr;</a>' +
        '</div>' +
        '<div class="kv-home-popular">' + popular.map(rankingCard).join('') + '</div>' +
      '</section>' +
      '<section class="kv-home-section" aria-labelledby="heading-curated">' +
        '<div class="kv-home-section-head">' +
          '<div><h2 class="kv-home-section-title" id="heading-curated">Rekomendasi</h2></div>' +
          '<a class="kv-home-link" href="#/archive">Koleksi Lengkap &rarr;</a>' +
        '</div>' +
        '<div class="kv-home-curated">' + curated + '</div>' +
      '</section>' +
    '</main>';
  }

   function renderMangaCard(m) {
     return '<article class="kv-card" data-action="open-manga" data-slug="' + escapeHtml(m.slug) + '" tabindex="0" role="button" aria-label="Buka detail ' + escapeHtml(m.title) + '">' +
       '<div class="kv-cover-wrap" style="border:none;border-radius:0;overflow:hidden;">' + renderCover(m.coverBloggerUrl, m.title) + '</div>' +
       '<div class="kv-card-body">' +
         '<div class="kv-meta-line">' + kvChip(m.type, true) + kvChip(m.status) + '</div>' +
         '<h3 class="kv-card-title">' + escapeHtml(m.title) + '</h3>' +
       '</div>' +
     '</article>';
   }

  /* =========================================================================
     HALAMAN ARCHIVE
     ========================================================================= */
  function sortLabel(sortBy) {
    if (sortBy === 'populer') return 'Terpopuler';
    if (sortBy === 'rating') return 'Rating Tertinggi';
    if (sortBy === 'abjad') return 'A - Z';
    return 'Terbaru';
  }

  function renderCatalog() {
     var allGenres = collectGenres();
     var typeOptions = ['Semua Tipe'].concat(collectTypes());
     var statusOptions = ['Semua Status', 'Ongoing', 'Tamat', 'Hiatus'];
     if (!Array.isArray(state.filterGenres)) state.filterGenres = [];
     state.filterGenres = state.filterGenres.filter(function (genre) { return allGenres.indexOf(genre) !== -1; });
     if (state.filterType === 'Semua') state.filterType = 'Semua Tipe';
     if (state.filterStatus === 'Semua') state.filterStatus = 'Semua Status';
     if (typeOptions.indexOf(state.filterType) === -1) state.filterType = 'Semua Tipe';
     if (statusOptions.indexOf(state.filterStatus) === -1) state.filterStatus = 'Semua Status';

    var list = state.data.manga.filter(function (m) {
      var matchQ = !state.search || m.title.toLowerCase().indexOf(state.search.toLowerCase()) !== -1;
       var matchG = state.filterGenres.length === 0 || (m.genres || []).some(function (genre) { return state.filterGenres.indexOf(genre) !== -1; });
       var matchS = state.filterStatus === 'Semua Status' || m.status === state.filterStatus;
       var matchT = state.filterType === 'Semua Tipe' || m.type === state.filterType;
      return matchQ && matchG && matchS && matchT;
    });

    list.sort(function (a, b) {
       if (state.sortBy === 'populer') return (b.views || 0) - (a.views || 0);
       if (state.sortBy === 'rating') return (b.rating || 0) - (a.rating || 0);
       if (state.sortBy === 'abjad') return a.title.localeCompare(b.title);
       return String(b.updatedAt || '').localeCompare(String(a.updatedAt || ''));
    });

    var totalPages = Math.max(1, Math.ceil(list.length / CONFIG.ITEMS_PER_PAGE));
    if (state.page > totalPages) state.page = totalPages;
    var paged = list.slice((state.page - 1) * CONFIG.ITEMS_PER_PAGE, state.page * CONFIG.ITEMS_PER_PAGE);

    var paginationHtml = '';
    if (totalPages > 1) {
      paginationHtml = '<div style="display:flex;justify-content:center;align-items:center;gap:12px;margin-top:28px;">' +
        '<button type="button" class="kv-btn kv-btn-ghost" id="kv-page-prev"' + (state.page === 1 ? ' disabled' : '') + '>&laquo; Sebelumnya</button>' +
        '<span class="kv-mono" style="color:var(--kv-text-muted);font-size:0.875rem;">Halaman ' + state.page + ' / ' + totalPages + '</span>' +
        '<button type="button" class="kv-btn kv-btn-ghost" id="kv-page-next"' + (state.page === totalPages ? ' disabled' : '') + '>Berikutnya &raquo;</button>' +
      '</div>';
    }

    return '<main class="kv-container kv-home-light kv-catalog-page">' +
      '<section class="kv-catalog-hero">' +
        '<div>' +
          '<div class="kv-home-kicker">Koleksi</div>' +
          '<h1 class="kv-home-section-title">Archive</h1>' +
          '<p class="kv-catalog-sub">Jelajahi seluruh judul berdasarkan genre, tipe, status, atau kata kunci.</p>' +
        '</div>' +
        '<span class="kv-catalog-count">' + list.length + ' judul</span>' +
      '</section>' +
      '<div class="kv-catalog-toolbar" data-catalog-toolbar="1" aria-label="Filter koleksi manga">' +
        '<label class="kv-search-wrap">' +
          '<svg class="kv-search-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M21 21l-4.35-4.35"/></svg>' +
          '<input id="kv-search-input" class="kv-input kv-search-input" type="search" placeholder="Cari judul manga..." value="' + escapeHtml(state.search) + '" aria-label="Cari judul manga"/>' +
        '</label>' +
        '<div class="kv-dropdown" data-dropdown="genre">' +
          '<button type="button" class="kv-dropdown-btn" id="kv-filter-genre-btn" aria-haspopup="dialog" aria-expanded="' + (state.openCatalogDropdown === 'genre' ? 'true' : 'false') + '" aria-controls="kv-filter-genre-panel">' +
            '<span class="kv-dropdown-label">Genre</span>' +
            '<span class="kv-dropdown-value">' + (state.filterGenres.length ? state.filterGenres.length + ' dipilih' : 'Semua Genre') + '</span>' +
            '<svg class="kv-dropdown-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>' +
          '</button>' +
          '<div class="kv-dropdown-panel kv-filter-panel' + (state.openCatalogDropdown === 'genre' ? ' is-open' : '') + '" id="kv-filter-genre-panel" role="dialog" aria-label="Pilih genre">' +
            '<div class="kv-filter-panel-head"><span>Pilih Genre</span><span class="kv-filter-panel-hint">' + state.filterGenres.length + ' dipilih</span></div>' +
            '<div class="kv-filter-panel-grid">' +
              allGenres.map(function (g) {
                var active = state.filterGenres.indexOf(g) !== -1;
                return '<label class="kv-check-chip' + (active ? ' is-checked' : '') + '"><input type="checkbox" class="kv-filter-check" data-genre="' + escapeHtml(g) + '"' + (active ? ' checked' : '') + '/><span>' + escapeHtml(g) + '</span></label>';
              }).join('') +
            '</div>' +
            '<div class="kv-filter-panel-foot">' +
              '<button type="button" class="kv-btn kv-btn-ghost" data-action="clear-genres">Hapus</button>' +
              '<button type="button" class="kv-btn kv-btn-primary" data-action="close-catalog-dropdowns">Selesai</button>' +
            '</div>' +
          '</div>' +
        '</div>' +
        '<div class="kv-dropdown" data-dropdown="type">' +
          '<button type="button" class="kv-dropdown-btn" id="kv-filter-type-btn" aria-haspopup="dialog" aria-expanded="' + (state.openCatalogDropdown === 'type' ? 'true' : 'false') + '" aria-controls="kv-filter-type-panel">' +
            '<span class="kv-dropdown-label">Tipe</span>' +
            '<span class="kv-dropdown-value">' + escapeHtml(state.filterType) + '</span>' +
            '<svg class="kv-dropdown-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>' +
          '</button>' +
          '<div class="kv-dropdown-panel' + (state.openCatalogDropdown === 'type' ? ' is-open' : '') + '" id="kv-filter-type-panel" role="dialog" aria-label="Pilih tipe manga">' +
            '<div class="kv-filter-panel-head"><span>Tipe</span></div>' +
            '<div class="kv-filter-options">' +
              typeOptions.map(function (t) {
                var active = state.filterType === t;
                return '<button type="button" class="kv-filter-option' + (active ? ' is-selected' : '') + '" data-action="set-filter-type" data-value="' + escapeHtml(t) + '"><span class="kv-check-dot"></span>' + escapeHtml(t) + '</button>';
              }).join('') +
            '</div>' +
            '<div class="kv-filter-panel-foot">' +
              '<button type="button" class="kv-btn kv-btn-primary" data-action="close-catalog-dropdowns">Selesai</button>' +
            '</div>' +
          '</div>' +
        '</div>' +
        '<div class="kv-dropdown" data-dropdown="status">' +
          '<button type="button" class="kv-dropdown-btn" id="kv-filter-status-btn" aria-haspopup="dialog" aria-expanded="' + (state.openCatalogDropdown === 'status' ? 'true' : 'false') + '" aria-controls="kv-filter-status-panel">' +
            '<span class="kv-dropdown-label">Status</span>' +
            '<span class="kv-dropdown-value">' + escapeHtml(state.filterStatus) + '</span>' +
            '<svg class="kv-dropdown-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>' +
          '</button>' +
          '<div class="kv-dropdown-panel' + (state.openCatalogDropdown === 'status' ? ' is-open' : '') + '" id="kv-filter-status-panel" role="dialog" aria-label="Pilih status manga">' +
            '<div class="kv-filter-panel-head"><span>Status</span></div>' +
            '<div class="kv-filter-options">' +
              statusOptions.map(function (st) {
                var active = state.filterStatus === st;
                return '<button type="button" class="kv-filter-option' + (active ? ' is-selected' : '') + '" data-action="set-filter-status" data-value="' + escapeHtml(st) + '"><span class="kv-check-dot"></span>' + escapeHtml(st) + '</button>';
              }).join('') +
            '</div>' +
            '<div class="kv-filter-panel-foot">' +
              '<button type="button" class="kv-btn kv-btn-primary" data-action="close-catalog-dropdowns">Selesai</button>' +
            '</div>' +
          '</div>' +
        '</div>' +
        '<div class="kv-dropdown kv-dropdown-right" data-dropdown="sort">' +
          '<button type="button" class="kv-dropdown-btn" id="kv-sort-by-btn" aria-haspopup="dialog" aria-expanded="' + (state.openCatalogDropdown === 'sort' ? 'true' : 'false') + '" aria-controls="kv-sort-by-panel">' +
            '<svg class="kv-sort-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 4v16"/><path d="M4 17l3 3 3-3"/><path d="M17 20V4"/><path d="M20 7l-3-3-3 3"/></svg>' +
            '<span class="kv-dropdown-value">' + escapeHtml(sortLabel(state.sortBy)) + '</span>' +
            '<svg class="kv-dropdown-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>' +
          '</button>' +
          '<div class="kv-dropdown-panel' + (state.openCatalogDropdown === 'sort' ? ' is-open' : '') + '" id="kv-sort-by-panel" role="dialog" aria-label="Urutkan koleksi">' +
            '<div class="kv-filter-panel-head"><span>Urutkan</span></div>' +
            '<div class="kv-filter-options">' +
              [['terbaru', 'Terbaru'], ['populer', 'Terpopuler'], ['rating', 'Rating Tertinggi'], ['abjad', 'A - Z']].map(function (item) {
                var active = state.sortBy === item[0];
                return '<button type="button" class="kv-filter-option' + (active ? ' is-selected' : '') + '" data-action="set-sort" data-value="' + item[0] + '"><span class="kv-check-dot"></span>' + item[1] + '</button>';
              }).join('') +
            '</div>' +
            '<div class="kv-filter-panel-foot">' +
              '<button type="button" class="kv-btn kv-btn-primary" data-action="close-catalog-dropdowns">Selesai</button>' +
            '</div>' +
          '</div>' +
        '</div>' +
      '</div>' +
      (paged.length === 0
        ? '<div class="kv-catalog-empty">Tidak ada manga yang cocok dengan filter Anda.</div>'
        : '<div class="kv-home-grid kv-catalog-grid">' + paged.map(renderLightCard).join('') + '</div>') +
       paginationHtml +
    '</main>';
  }

  /* =========================================================================
     HALAMAN DETAIL MANGA
     ========================================================================= */
  function renderCommentSection(manga, chapterId) {
    var comments = state.data.comments.filter(function (c) {
      return c.mangaId === manga.id && (chapterId ? c.chapterId === chapterId : true);
    });
    var aggregated = !chapterId;
    var sectionNote = aggregated ? 'Semua reaksi dari seluruh chapter digabung di sini. Beri reaksi di halaman chapter agar tercatat per-chapter.' : 'Komentar ini khusus chapter ini.';
    var myDisplayName = state.user ? currentDisplayName(state.user.name) : 'Pengguna';
    var myDisplayAvatar = state.user ? currentDisplayAvatar(state.user.avatar || null) : null;
    return '<section class="kv-detail-card">' +
            '<div class="kv-detail-card-head">' +
              '<div class="kv-detail-card-title">Komentar <span class="kv-detail-count">' + comments.length + '</span></div>' +
              '<span class="kv-detail-card-note">Hormati sesama pembaca</span>' +
            '</div>' +
            '<p class="kv-comment-scope-note">' + escapeHtml(sectionNote) + '</p>' +
            '<div class="kv-comment-rules" role="note" aria-label="Aturan berkomentar">' +
              '<div class="kv-comment-rules-head"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>Papan Aturan Berkomentar</div>' +
              '<ul class="kv-comment-rules-list">' +
                '<li>Hormati sesama pembaca: dilarang SARA, hinaan, dan ujaran kebencian.</li>' +
                '<li>Dilarang spam, promosi, tautan iklan, dan berbagi konten ilegal.</li>' +
                '<li>Jangan bagikan spoiler tanpa tanda ||spoiler||.</li>' +
                '<li>Gunakan bahasa yang sopan dan relevan dengan manga ini.</li>' +
                '<li>Komentar dapat dimoderasi atau dihapus admin jika melanggar aturan.</li>' +
              '</ul>' +
            '</div>' +
            (function () {
              var summary = aggregated ? aggregateChapterReactions(manga) : chapterReactionSummary(chapterId);
              var reactions = [
                { key: 'fire', emoji: '&#128293;', label: 'Semangat' },
                { key: 'shock', emoji: '&#128562;', label: 'Kaget' },
                { key: 'cry', emoji: '&#128557;', label: 'Nangis' },
                { key: 'laugh', emoji: '&#128514;', label: 'Lucu' },
                { key: 'angry', emoji: '&#128545;', label: 'Marah' }
              ];
              if (aggregated) {
                return '<div class="kv-comment-reaction">' +
                  '<div class="kv-comment-reaction-label">Reaksi</div>' +
                  '<div class="kv-manga-reaction-row" role="status" aria-label="Reaksi">' +
                    reactions.map(function (item) {
                      var total = summary.counts[item.key] || 0;
                      return '<span class="kv-manga-reaction kv-manga-reaction-static" title="' + item.label + '">' +
                        '<span class="kv-manga-reaction-emoji" aria-hidden="true">' + item.emoji + '</span>' +
                        '<span class="kv-manga-reaction-count">' + total + '</span>' +
                        '<span class="kv-manga-reaction-label">' + item.label + '</span>' +
                      '</span>';
                    }).join('') +
        '</div>';
   }

              return '<div class="kv-comment-reaction">' +
                '<div class="kv-comment-reaction-label">Reaksi untuk chapter ini</div>' +
                '<div class="kv-manga-reaction-row" role="group" aria-label="Reaksi chapter">' +
                  reactions.map(function (item) {
                    var active = summary.userVote === item.key;
                    return '<button type="button" class="kv-manga-reaction' + (active ? ' active' : '') + '" data-action="chapter-reaction" data-id="' + escapeHtml(chapterId || '') + '" data-reaction="' + item.key + '" aria-pressed="' + (active ? 'true' : 'false') + '" title="' + item.label + '">' +
                      '<span class="kv-manga-reaction-emoji" aria-hidden="true">' + item.emoji + '</span>' +
                      '<span class="kv-manga-reaction-count">' + (summary.counts[item.key] || 0) + '</span>' +
                      '<span class="kv-manga-reaction-label">' + item.label + '</span>' +
                    '</button>';
                  }).join('') +
                '</div>' +
              '</div>';
            })() +
            (state.commentNotice ? '<div class="kv-detail-notice">' + escapeHtml(state.commentNotice) + '</div>' : '') +
            '<form id="kv-comment-form" data-manga-id="' + escapeHtml(manga.id) + '" data-chapter-id="' + escapeHtml(chapterId || '') + '" class="kv-comment-form kv-detail-comment-form">' +
              '<div class="kv-comment-form-head">' +
                (myDisplayAvatar ? '<img src="' + escapeHtml(myDisplayAvatar) + '" alt="" class="kv-comment-avatar" referrerpolicy="no-referrer"/>' : '<div class="kv-comment-avatar kv-comment-avatar-fallback">' + escapeHtml(myDisplayName.charAt(0).toUpperCase()) + '</div>') +
                '<div><div class="kv-comment-name">' + (state.user ? escapeHtml(myDisplayName) : 'Tulis komentar Anda') + '</div><div class="kv-comment-hint">Profile kamu.</div></div>' +
              '</div>' +
              (state.user ? '' : '<input class="kv-input kv-detail-input" name="author" placeholder="Nama Anda" required/>') +
              '<textarea class="kv-textarea kv-detail-textarea" name="content" placeholder="Tulis komentar..." required rows="3"></textarea>' +
              '<div class="kv-comment-form-foot">' +
                '<span class="kv-comment-hint">Gunakan **tebal**, *miring*, ||spoiler||</span>' +
                '<button type="button" class="kv-btn kv-btn-ghost kv-comment-image-btn" data-action="comment-image" title="Unggah gambar" aria-label="Unggah gambar"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg></button>' +
                '<button class="kv-btn kv-btn-primary kv-detail-submit" type="submit">Kirim Komentar</button>' +
              '</div>' +
            '</form>' +
            '<input type="file" id="kv-comment-image-file" accept="image/jpeg,image/png,image/webp" style="display:none;"/>' +
            (function () {
              var voterKey = state.user ? state.user.id : voterId();
              var byParent = {};
              comments.forEach(function (c) {
                var key = c.parentId || '';
                if (!byParent[key]) byParent[key] = [];
                byParent[key].push(c);
              });
              function oldestFirst(list) {
                return list.slice().sort(function (a, b) {
                  return String(a.createdAt || '').localeCompare(String(b.createdAt || '')) || String(a.id || '').localeCompare(String(b.id || ''));
                });
              }
              function chapterBadge(comment) {
                if (!comment.chapterId) return '';
                var ch = state.data.chapters.filter(function (item) { return item.id === comment.chapterId; })[0];
                if (!ch) return '';
                return '<span class="kv-comment-chapter-badge">Ch. ' + escapeHtml(ch.number) + '</span>';
              }
              function pinnedBadge(comment) {
                if (!comment.pinned) return '';
                return '<span class="kv-comment-pinned"><svg viewBox="0 0 24 24" fill="currentColor" stroke="none" aria-hidden="true"><path d="M9 4v7L7 14v3h10v-3l-2-3V4m-6 0V3h6v1"/></svg>Disematkan</span>';
              }
              function adminCommentActions(c) {
                var isAdmin = state.user && state.user.role === 'admin';
                if (!isAdmin) return '';
                var pinIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 4v7l-2 4v3h10v-3l-2-4V4M10 4h4M12 18v3"/></svg>';
                var trashIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>';
                return '<button type="button" class="kv-comment-action kv-comment-action-admin' + (c.pinned ? ' active' : '') + '" data-action="admin-pin-comment" data-id="' + escapeHtml(c.id) + '" aria-pressed="' + (c.pinned ? 'true' : 'false') + '" title="' + (c.pinned ? 'Lepas pin' : 'Sematkan komentar') + '">' + pinIcon + '</button>' +
                  '<button type="button" class="kv-comment-action kv-comment-action-admin kv-comment-action-danger" data-action="admin-delete-comment" data-id="' + escapeHtml(c.id) + '" title="Hapus komentar">' + trashIcon + '</button>';
              }
              function renderComment(c, depth) {
                var upvotes = Array.isArray(c.upvotes) ? c.upvotes : [];
                var voted = upvotes.indexOf(voterKey) !== -1;
                var own = state.user && c.userId && c.userId === state.user.id;
                var authorName = own ? myDisplayName : c.authorName;
                var authorAvatar = own ? myDisplayAvatar : c.authorAvatar;
                var avatar = authorAvatar ? '<img src="' + escapeHtml(authorAvatar) + '" alt="" class="kv-comment-avatar" referrerpolicy="no-referrer"/>' : '<div class="kv-comment-avatar kv-comment-avatar-fallback">' + escapeHtml(String(authorName || '?').charAt(0).toUpperCase()) + '</div>';
                var rootId = depth === 0 ? c.id : c.parentId;
                var replyToBadge = c.replyTo ? '<span class="kv-reply-to">@' + escapeHtml(c.replyTo) + '</span>' : '';
                var contentHtml = renderCommentContent(c.content);
                var imageHtml = c.imageUrl ? '<img class="kv-comment-image" src="' + escapeHtml(c.imageUrl) + '" alt="Gambar dari ' + escapeHtml(authorName) + '" loading="lazy" referrerpolicy="no-referrer"/>' : '';
                var replyForm = state.replyingTo === c.id
                  ? '<form class="kv-reply-form kv-comment-reply-form" data-manga-id="' + escapeHtml(manga.id) + '" data-chapter-id="' + escapeHtml(chapterId || '') + '" data-parent-id="' + escapeHtml(rootId) + '" data-reply-to="' + escapeHtml(authorName) + '">' +
                      (state.user ? '' : '<input class="kv-input kv-detail-input" name="author" placeholder="Nama Anda" required/>') +
                      '<textarea class="kv-textarea kv-detail-textarea" name="content" placeholder="Tulis balasan..." required rows="3"></textarea>' +
                      '<div class="kv-comment-reply-actions">' +
                        '<button type="button" class="kv-btn kv-btn-ghost kv-comment-image-btn" data-action="comment-image" title="Unggah gambar" aria-label="Unggah gambar"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg></button>' +
                        '<button type="button" class="kv-btn kv-btn-ghost" data-action="reply-comment" data-id="' + escapeHtml(c.id) + '">Batal</button>' +
                        '<button class="kv-btn kv-btn-primary" type="submit">Kirim Balasan</button>' +
                      '</div>' +
                    '</form>'
                  : '';
                var children = depth === 0 ? oldestFirst(byParent[c.id] || []) : [];
                var isExpanded = state.expandedComments && state.expandedComments[c.id] === true;
                var repliesToggle = children.length > 0
                  ? '<button type="button" class="kv-comment-toggle-replies' + (isExpanded ? ' is-open' : '') + '" data-action="toggle-replies" data-id="' + escapeHtml(c.id) + '" aria-expanded="' + (isExpanded ? 'true' : 'false') + '">' +
                      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>' +
                      (isExpanded ? 'Tutup ' : 'Tampilkan balasan (') + children.length + (isExpanded ? '' : ')') +
                    '</button>'
                  : '';
                var childrenHtml = (isExpanded && children.length) ? '<div class="kv-detail-comment-children">' + children.map(function (k) { return renderComment(k, 1); }).join('') + '</div>' : '';
                return '<div class="kv-detail-comment' + (depth ? ' kv-detail-comment-child' : '') + '">' +
                  '<div class="kv-detail-comment-card">' +
                    '<div class="kv-detail-comment-main">' + avatar +
                      '<div class="kv-detail-comment-body">' +
                        '<div class="kv-detail-comment-head">' +
                          '<strong>' + escapeHtml(authorName) + '</strong>' + (own ? '<span class="kv-detail-comment-you">(Anda)</span>' : '') +
                          replyToBadge +
                          chapterBadge(c) +
                          pinnedBadge(c) +
                          '<span class="kv-detail-comment-date">' + escapeHtml(c.createdAt || '') + '</span>' +
                        '</div>' +
                        '<div class="kv-detail-comment-text">' + contentHtml + '</div>' +
                        imageHtml +
                         '<div class="kv-detail-comment-actions">' +
                           '<button type="button" class="kv-comment-action' + (voted ? ' active' : '') + '" data-action="upvote-comment" data-id="' + escapeHtml(c.id) + '" aria-pressed="' + (voted ? 'true' : 'false') + '" title="' + (voted ? 'Batalkan suka' : 'Suka') + '"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 9V5a3 3 0 0 0-3-3l-4 9v10h11.28a2 2 0 0 0 2-1.7l.96-6.5A2 2 0 0 0 19.28 10H14z"/><path d="M7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/></svg>' + ' ' + upvotes.length + '</button>' +
                           '<button type="button" class="kv-comment-action" data-action="reply-comment" data-id="' + escapeHtml(c.id) + '">Balas</button>' +
                           adminCommentActions(c) +
                         '</div>' +
                         (repliesToggle ? '<div class="kv-comment-replies-toggle-wrap">' + repliesToggle + '</div>' : '') +
                         replyForm +

                      '</div>' +
                    '</div>' +
                  '</div>' +
                  childrenHtml +
                '</div>';
              }
               var sortMode = state.commentSort || 'newest';
               var topLevel = (byParent[''] || []).slice().sort(function (a, b) {
                 var ap = a.pinned ? 1 : 0;
                 var bp = b.pinned ? 1 : 0;
                 if (ap !== bp) return bp - ap;
                 if (sortMode === 'oldest') {
                   return String(a.createdAt || '').localeCompare(String(b.createdAt || '')) || String(a.id || '').localeCompare(String(b.id || ''));
                 }
                 return String(b.createdAt || '').localeCompare(String(a.createdAt || '')) || String(b.id || '').localeCompare(String(a.id || ''));
               });

               var sortBar = '<div class="kv-comment-sortbar">' +
                 '<span class="kv-comment-sortlabel">Urutkan:</span>' +
                 '<button type="button" class="kv-btn kv-btn-sm ' + (sortMode === 'newest' ? 'kv-btn-primary' : 'kv-btn-ghost') + '" data-action="set-comment-sort" data-sort="newest">Terbaru</button>' +
                 '<button type="button" class="kv-btn kv-btn-sm ' + (sortMode === 'oldest' ? 'kv-btn-primary' : 'kv-btn-ghost') + '" data-action="set-comment-sort" data-sort="oldest">Terdahulu</button>' +
               '</div>';
               return sortBar + (topLevel.map(function (c) { return renderComment(c, 0); }).join('') || '<p class="kv-detail-empty">Belum ada komentar. Jadilah yang pertama.</p>');

            })() +
          '</section>' 
  }

  function renderDetail() {
    var manga = state.data.manga.filter(function (m) { return m.slug === state.params.slug; })[0];
    if (!manga) return render404();

    var chapterQuery = String(state.chapterSearch || '').toLowerCase();
    var chs = state.data.chapters.filter(function (c) { return c.mangaId === manga.id; }).slice();
    chs = chs.filter(function (c) {
      if (!chapterQuery) return true;
      var hay = (String(c.number) + ' ' + (c.title || '')).toLowerCase();
      return hay.indexOf(chapterQuery) !== -1;
    });
    chs.sort(function (a, b) { return state.chapterSortAsc ? a.number - b.number : b.number - a.number; });
    var allChapters = state.data.chapters.filter(function (c) { return c.mangaId === manga.id; });
    var maxChapter = allChapters.reduce(function (max, c) { return Math.max(max, c.number); }, 0);
    var latestChapter = allChapters.slice().sort(function (a, b) { return b.number - a.number; })[0];
    var firstCh = allChapters.slice().sort(function (a, b) { return a.number - b.number; })[0];
    var isBookmarked = state.bookmarks.indexOf(manga.id) !== -1;
    var rating = Number(manga.rating || 0).toFixed(2);
    var views = (manga.views || 0).toLocaleString('id-ID');
    var recommended = state.data.manga.filter(function (m) { return m.id !== manga.id && (m.genres || []).some(function (g) { return (manga.genres || []).indexOf(g) !== -1; }); });
    if (recommended.length < 4) {
      var extra = state.data.manga.filter(function (m) { return m.id !== manga.id && recommended.indexOf(m) === -1; }).slice(0, 4 - recommended.length);
      recommended = recommended.concat(extra);
    }
    recommended = recommended.slice(0, 4);

    return '<main class="kv-container kv-detail-page">' +
      '<nav class="kv-detail-breadcrumb" aria-label="Breadcrumb">' +
        '<ol><li><a href="#/">Beranda</a></li><li>/</li><li><a href="#/archive">Archive</a></li><li>/</li><li aria-current="page">' + escapeHtml(manga.title) + '</li></ol>' +
      '</nav>' +
      '<section class="kv-detail-hero">' +
        '<div class="kv-detail-hero-cover">' + renderCover(manga.coverBloggerUrl, manga.title) + '</div>' +
        '<div class="kv-detail-hero-body">' +
          '<div class="kv-detail-chip-row">' +
            '<span class="kv-detail-badge kv-detail-badge-primary">' + escapeHtml(manga.type || 'Manga') + '</span>' +
            '<span class="kv-detail-badge kv-detail-badge-status">' + escapeHtml(manga.status || 'Ongoing') + '</span>' +
            (manga.featured ? '<span class="kv-detail-badge kv-detail-badge-pick">Pilihan Editor</span>' : '') +
          '</div>' +
          '<h1 class="kv-detail-title">' + escapeHtml(manga.title) + '</h1>' +
          (manga.altTitle ? '<p class="kv-detail-alt">' + escapeHtml(manga.altTitle) + '</p>' : '') +
          '<div class="kv-detail-metrics">' +
            '<div class="kv-detail-metric"><span class="kv-detail-metric-label">Total Dibaca</span><span class="kv-detail-metric-value">' + escapeHtml(views) + '</span></div>' +
            '<div class="kv-detail-metric"><span class="kv-detail-metric-label">Skor Rating</span><span class="kv-detail-metric-value kv-detail-metric-accent">&#9733; ' + escapeHtml(rating) + '</span></div>' +
            '<div class="kv-detail-metric"><span class="kv-detail-metric-label">Author</span><span class="kv-detail-metric-value kv-detail-metric-truncate">' + escapeHtml(manga.author || '-') + '</span></div>' +
            '<div class="kv-detail-metric"><span class="kv-detail-metric-label">Rilis &amp; Status</span><span class="kv-detail-metric-value">' + escapeHtml(manga.status || 'Ongoing') + '</span></div>' +
          '</div>' +
          '<div class="kv-detail-genres">' + (manga.genres || []).map(function (g) { return '<button type="button" class="kv-detail-genre kv-detail-genre-link" data-action="quick-genre" data-genre="' + escapeHtml(g) + '">' + escapeHtml(g) + '</button>'; }).join('') + '</div>' +
          '<div class="kv-detail-actions">' +
            (latestChapter ? '<a class="kv-detail-primary" href="#/baca/' + escapeHtml(manga.slug) + '/' + escapeHtml(latestChapter.id) + '">Baca Chapter Terbaru (Ch. ' + latestChapter.number + ')</a>' : '') +
            (firstCh && firstCh.id !== (latestChapter && latestChapter.id) ? '<a class="kv-detail-secondary" href="#/baca/' + escapeHtml(manga.slug) + '/' + escapeHtml(firstCh.id) + '">Chapter Pertama (Ch. ' + firstCh.number + ')</a>' : '') +
            '<button type="button" class="kv-detail-secondary" data-action="toggle-bookmark" data-id="' + escapeHtml(manga.id) + '">' + (isBookmarked ? 'Tersimpan di Favorit' : 'Simpan Favorit') + '</button>' +
            '<button type="button" class="kv-detail-icon-btn" data-action="share-manga" title="Bagikan tautan">' + kvIcon('share') + '</button>' +
          '</div>' +
        '</div>' +
      '</section>' +
      '<div class="kv-detail-layout">' +
        '<div class="kv-detail-main">' +
          '<section class="kv-detail-card kv-detail-info-card">' +
            '<div class="kv-detail-card-title">Informasi Rinci</div>' +
            '<div class="kv-detail-info-row"><span>Format</span><strong>Webtoon / Digital</strong></div>' +
            '<div class="kv-detail-info-row"><span>Jadwal Rilis</span><strong>Mengikuti update</strong></div>' +
            '<div class="kv-detail-info-row"><span>Bahasa</span><strong>Bahasa Indonesia</strong></div>' +
            '<div class="kv-detail-info-row"><span>Author</span><strong>' + escapeHtml(manga.author || '-') + '</strong></div>' +
            '<div class="kv-detail-info-row"><span>Status</span><strong>' + escapeHtml(manga.status || 'Ongoing') + '</strong></div>' +
            '<div class="kv-detail-info-row"><span>Total Chapter</span><strong>' + allChapters.length + '</strong></div>' +
          '</section>' +
          '<section class="kv-detail-card">' +
            '<div class="kv-detail-card-head"><div class="kv-detail-card-title"><span class="kv-detail-dot"></span>Sinopsis Cerita</div><span class="kv-detail-card-note">Official Synopsis</span></div>' +
            '<p class="kv-detail-synopsis">' + escapeHtml(manga.synopsis) + '</p>' +
          '</section>' +
          '<section class="kv-detail-card">' +
            '<div class="kv-detail-card-head kv-detail-card-head-wrap">' +
              '<div class="kv-detail-card-title">Daftar Chapter <span class="kv-detail-count">' + allChapters.length + ' Chapter</span></div>' +
              '<div class="kv-detail-chapter-tools">' +
                '<div class="kv-detail-search-wrap">' + kvIcon('search') + '<input type="text" id="chapter-search" placeholder="Cari bab..." value="' + escapeHtml(state.chapterSearch || '') + '"/></div>' +
                '<button type="button" class="kv-detail-icon-btn" data-action="toggle-ch-sort" title="Ubah urutan">' + (state.chapterSortAsc ? '&#8593;' : '&#8595;') + '</button>' +
              '</div>' +
            '</div>' +
            '<div class="kv-detail-chapter-list">' +
              (chs.length ? chs.map(function (c) {
                var isNew = c.number === maxChapter;
                return '<div class="kv-detail-chapter-item" data-action="open-reader" data-slug="' + escapeHtml(manga.slug) + '" data-cid="' + escapeHtml(c.id) + '" tabindex="0" role="button" aria-label="Baca Chapter ' + c.number + '">' +
                  '<div class="kv-detail-chapter-info">' +
                    '<span class="kv-detail-chapter-title">Chapter ' + escapeHtml(c.number) + (c.title ? ': <span>' + escapeHtml(c.title) + '</span>' : '') + '</span>' +
                    (isNew ? '<span class="kv-detail-chapter-new">Baru</span>' : '') +
                  '</div>' +
                  '<span class="kv-detail-chapter-date">' + escapeHtml(c.publishedAt || '') + '</span>' +
                '</div>';
              }).join('') : '<p class="kv-detail-empty">Tidak ada chapter yang cocok.</p>') +
            '</div>' +
          '</section>' +
          renderCommentSection(manga, null) +
        '</div>' +
        '<aside class="kv-detail-sidebar">' +
          '<section class="kv-detail-card">' +
            '<div class="kv-detail-card-head">' +
              '<div class="kv-detail-card-title">Komik Rekomendasi</div>' +
              '<a class="kv-detail-card-note kv-detail-link" href="#/archive">Lihat Semua</a>' +
            '</div>' +
            '<div class="kv-detail-reco-list">' +
              recommended.map(function (m) {
                var latest = state.data.chapters.filter(function (c) { return c.mangaId === m.id; }).sort(function (a, b) { return b.number - a.number; })[0];
                var r = Number(m.rating || 0).toFixed(1);
                return '<a class="kv-detail-reco-item" href="#/manga/' + escapeHtml(m.slug) + '">' +
                  '<div class="kv-detail-reco-cover"><img src="' + escapeHtml(m.coverBloggerUrl || '') + '" alt="' + escapeHtml(m.title) + '" loading="lazy" referrerpolicy="no-referrer"/></div>' +
                  '<div class="kv-detail-reco-body">' +
                    '<h4>' + escapeHtml(m.title) + '</h4>' +
                    '<div class="kv-detail-reco-meta">' + (latest ? 'Ch. ' + escapeHtml(latest.number) + ' &middot; ' : '') + escapeHtml((m.genres || []).slice(0, 2).join(', ')) + '</div>' +
                  '</div>' +
                  '<div class="kv-detail-reco-rating">&#9733; ' + escapeHtml(r) + '</div>' +
                '</a>';
              }).join('') +
            '</div>' +
          '</section>' +
        '</aside>' +
      '</div>' +
    '</main>';
  }

  /* =========================================================================
     READER / VIEWER
     ========================================================================= */
  function renderReader() {
    var manga = state.data.manga.filter(function (m) { return m.slug === state.params.slug; })[0];
    var chapter = state.data.chapters.filter(function (c) { return c.id === state.params.chapterId; })[0];
    if (!manga || !chapter) return render404();

    var allCh = state.data.chapters.filter(function (c) { return c.mangaId === manga.id; }).sort(function (a, b) { return a.number - b.number; });
    var idx = -1;
    for (var i = 0; i < allCh.length; i++) { if (allCh[i].id === chapter.id) idx = i; }
    var prevCh = idx > 0 ? allCh[idx - 1] : null;
    var nextCh = idx >= 0 && idx < allCh.length - 1 ? allCh[idx + 1] : null;

     saveHistory(manga.id, chapter.id, chapter.number);

     if (!state.viewedChapters) state.viewedChapters = {};
     if (!state.viewedChapters[chapter.id]) {
       state.viewedChapters[chapter.id] = true;
       var viewedManga = state.data.manga.filter(function (m) { return m.id === manga.id; })[0];
       if (viewedManga) {
         viewedManga.views = (viewedManga.views || 0) + 1;
         persistData();
         if (CONFIG.API_BASE_URL) {
           fetch(CONFIG.API_BASE_URL + '/api/manga/view', {
             method: 'POST',
             headers: { 'Content-Type': 'application/json' },
             body: JSON.stringify({ id: viewedManga.id })
           }).then(function (r) { return r.ok ? r.json() : null; }).then(function (res) {
             if (res && typeof res.views === 'number' && viewedManga) viewedManga.views = res.views;
             render();
           }).catch(function () {});
         }
       }
     }

    var pageTotal = chapter.pages.length;
    var pagesHtml = '';
    if (state.readerMode === 'vertical') {
      pagesHtml = chapter.pages.map(function (p, index) {
        return renderReaderPage(p, manga.title, chapter.number, index + 1, pageTotal);
      }).join('');
    } else {
      if (state.currentPageIdx >= pageTotal) state.currentPageIdx = 0;
      var page = chapter.pages[state.currentPageIdx] || chapter.pages[0];
      pagesHtml = page ? renderReaderPage(page, manga.title, chapter.number, state.currentPageIdx + 1, pageTotal, true) : '<div class="kv-reader-placeholder"><div class="kv-reader-placeholder-inner"><strong>Belum ada halaman</strong><small>Chapter ini belum memiliki halaman.</small></div></div>';
    }

    var isVertical = state.readerMode === 'vertical';
    var frame = '<section class="kv-reader-frame ' + (isVertical ? 'vertical' : 'horizontal') + '" aria-label="Halaman manga">' +
      pagesHtml +
    '</section>';
    var isPlaying = !!state.autoScroll;
     var chQuery = String(state.readerChapterSearch || '').toLowerCase();
     var filteredCh = allCh.filter(function (c) {
       if (!chQuery) return true;
       var hay = (String(c.number) + ' ' + (c.title || '')).toLowerCase();
       return hay.indexOf(chQuery) !== -1;
     });
     var chapterRows = filteredCh.map(function (c) {
       var active = c.id === chapter.id;

      return '<a class="kv-reader-chapter-row' + (active ? ' is-active' : '') + '" href="#/baca/' + escapeHtml(manga.slug) + '/' + escapeHtml(c.id) + '">' +
        '<span class="kv-reader-chapter-num">Ch. ' + escapeHtml(c.number) + '</span>' +
        '<span class="kv-reader-chapter-name">' + (c.title ? escapeHtml(c.title) : 'Chapter ' + escapeHtml(c.number)) + '</span>' +
      '</a>';
    }).join('');
    var gearIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="3.1"/><path d="M12 2.7v2.8M12 18.5v2.8M5.5 5.5l2 2M16.5 16.5l2 2M2.7 12h2.8M18.5 12h2.8M5.5 18.5l2-2M16.5 7.5l2-2"/></svg>';
     var prevIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 6l-6 6 6 6"/></svg>';
     var nextIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg>';
    var menuIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"/></svg>';
    var homeIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 11L12 3L21 11"/><path d="M5 10V21H19V10"/></svg>';
    var playIcon = '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M8 5v14l11-7z"/></svg>';
    var pauseIcon = '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M7 5h4v14H7zM13 5h4v14h-4z"/></svg>';

    var settingsSheet = '<div class="kv-reader-sheet" role="dialog" aria-modal="true" aria-label="Pengaturan pembaca">' +
      '<div class="kv-reader-sheet-head"><span>Pengaturan Pembaca</span><button type="button" class="kv-reader-sheet-close" data-action="close-reader-panels" aria-label="Tutup">&times;</button></div>' +
       '<div class="kv-reader-sheet-body">' +
         '<div class="kv-reader-sheet-row"><span class="kv-reader-sheet-label">Tema</span>' +
           '<button type="button" class="kv-btn kv-btn-ghost kv-theme-toggle" data-action="toggle-theme" aria-label="' + (state.theme === 'dark' ? 'Aktifkan mode terang' : 'Aktifkan mode gelap') + '" title="' + (state.theme === 'dark' ? 'Aktifkan mode terang' : 'Aktifkan mode gelap') + '" style="width:44px;height:44px;flex-basis:44px;">' +
             (state.theme === 'dark'
               ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/></svg>'
               : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13z"/></svg>') +
           '</button>' +
         '</div>' +
         '<div class="kv-reader-sheet-row"><label class="kv-reader-sheet-label" for="kv-reader-speed">Kecepatan gulir (px/tick)</label>' +
           '<input id="kv-reader-speed" class="kv-input kv-mono" type="number" min="0.5" max="20" step="0.5" value="' + (state.autoScrollSpeed || 2.5) + '" style="width:90px;" data-action="reader-speed-input"/>' +
         '</div>' +
         '<div class="kv-reader-sheet-row"><span class="kv-reader-sheet-label">Layar penuh</span>' +
           '<button type="button" class="kv-reader-ctl kv-reader-ctl-primary" data-action="toggle-fullscreen">&#9974; Layar Penuh</button>' +
         '</div>' +


      '</div>' +
    '</div>';

    var menuBookmarked = state.bookmarks.indexOf(manga.id) !== -1;
    var menuSheet = '<div class="kv-reader-sheet" role="dialog" aria-modal="true" aria-label="Daftar chapter">' +
      '<div class="kv-reader-sheet-head"><span>' + escapeHtml(manga.title) + ' &middot; Ch. ' + escapeHtml(chapter.number) + '</span><button type="button" class="kv-reader-sheet-close" data-action="close-reader-panels" aria-label="Tutup">&times;</button></div>' +
      '<div class="kv-reader-sheet-body">' +
         '<div class="kv-reader-sheet-actions">' +
            '<a class="kv-reader-ctl" href="#/manga/' + escapeHtml(manga.slug) + '">&#8592; ' + escapeHtml(manga.title) + '</a>' +
         '</div>' +
         '<div class="kv-reader-sheet-row">' +
           '<input id="kv-reader-chapter-search" class="kv-input" type="search" placeholder="Cari chapter..." value="' + escapeHtml(state.readerChapterSearch || '') + '" aria-label="Cari chapter"/>' +
         '</div>' +
         '<div class="kv-reader-chapter-list" role="list">' + (chapterRows || '<p class="kv-reader-chapter-name">Belum ada chapter.</p>') + '</div>' +

      '</div>' +
    '</div>';

    var overlay = '<div class="kv-reader-overlay" id="kv-reader-overlay" role="group" aria-label="Kontrol pembaca">' +
      '<div class="kv-reader-side">' +
        '<button type="button" class="kv-round-btn" data-action="scroll-reader-up" aria-label="Gulir ke atas"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 15L12 8L19 15"/></svg></button>' +
        '<button type="button" class="kv-round-btn" data-action="scroll-reader-down" aria-label="Gulir ke bawah"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 9L12 16L19 9"/></svg></button>' +
      '</div>' +
      '<div class="kv-reader-bottom-controls">' +
         (prevCh
           ? '<a class="kv-round-btn" href="#/baca/' + escapeHtml(manga.slug) + '/' + escapeHtml(prevCh.id) + '" aria-label="Chapter sebelumnya">' + prevIcon + '</a>'
           : '<button type="button" class="kv-round-btn is-disabled" disabled aria-label="Tidak ada chapter sebelumnya">' + prevIcon + '</button>') +
         (nextCh
           ? '<a class="kv-round-btn kv-round-btn-next" href="#/baca/' + escapeHtml(manga.slug) + '/' + escapeHtml(nextCh.id) + '" aria-label="Chapter berikutnya">' + nextIcon + '</a>'
           : '<button type="button" class="kv-round-btn is-disabled" disabled aria-label="Tidak ada chapter berikutnya">' + nextIcon + '</button>') +

        '<button type="button" class="kv-round-btn" data-action="toggle-reader-settings" aria-label="Pengaturan pembaca" aria-expanded="' + (state.readerSettingsOpen ? 'true' : 'false') + '">' + gearIcon + '</button>' +
        '<button type="button" class="kv-round-btn kv-round-btn-play' + (isPlaying ? ' is-active' : '') + '" data-action="toggle-auto-scroll" aria-label="' + (isPlaying ? 'Hentikan' : 'Mulai') + ' gulir otomatis" aria-pressed="' + (isPlaying ? 'true' : 'false') + '">' + (isPlaying ? pauseIcon : playIcon) + '</button>' +
        '<button type="button" class="kv-round-btn" data-action="toggle-reader-menu" aria-label="Daftar chapter" aria-expanded="' + (state.readerMenuOpen ? 'true' : 'false') + '">' + menuIcon + '</button>' +
        '<a class="kv-round-btn" href="#/" aria-label="Kembali ke Beranda">' + homeIcon + '</a>' +
      '</div>' +
    '</div>' +
    ((state.readerSettingsOpen || state.readerMenuOpen) ? '<div class="kv-reader-scrim" data-action="close-reader-panels" aria-hidden="true"></div>' : '') +
    (state.readerSettingsOpen ? settingsSheet : '') +
    (state.readerMenuOpen ? menuSheet : '');
    var notice = '<p class="kv-reader-notice">Jika gambar tidak muncul, muat ulang halaman atau coba beberapa saat lagi.</p>';

    return '<div class="kv-reader-shell">' +
      '<main class="kv-reader-page">' +
        '<div class="kv-reader-top-spacer" aria-hidden="true"></div>' +
        frame +
        overlay +
        renderCommentSection(manga, chapter.id) +
        notice +
      '</main>' +
    '</div>';
  }

  function renderReaderPage(p, title, chNum, pageIndex, pageTotal, isActive) {
    var mediaUrl = '';
    if (p.bloggerUrl) {
      mediaUrl = p.bloggerUrl;
    } else if (CONFIG.API_BASE_URL && p.telegramFileId) {
      mediaUrl = CONFIG.API_BASE_URL + '/api/media/' + encodeURIComponent(p.telegramFileId);
    }
    var figureClass = 'manga-page' + (isActive ? ' is-active' : '');
    if (!mediaUrl) {
      return '<div class="' + figureClass + ' kv-reader-placeholder">' +
        '<div class="kv-reader-placeholder-inner"><strong>Halaman ' + pageIndex + ' belum tersedia</strong><small>Halaman ini belum memiliki URL media di database.</small></div>' +
      '</div>';
    }
    return '<figure class="' + figureClass + '"><img src="' + escapeHtml(mediaUrl) + '" alt="' + escapeHtml(title) + ' Chapter ' + chNum + ' Halaman ' + escapeHtml(p.order || pageIndex) + '" loading="lazy" referrerpolicy="no-referrer"/></figure>';
  }

  function saveHistory(mangaId, chapterId, chapterNumber) {
    var list = state.history.filter(function (h) { return h.mangaId !== mangaId; });
    list.unshift({ mangaId: mangaId, chapterId: chapterId, chapterNumber: chapterNumber, lastReadAt: new Date().toISOString().slice(0, 10) });
    state.history = list.slice(0, 20);
    localStorage.setItem('kv_history', JSON.stringify(state.history));
  }

  /* =========================================================================
     AKUN PEMBACA & HALAMAN INFORMASI & ADMIN
     ========================================================================= */
  function renderAccount() {
    var favManga = state.data.manga.filter(function (m) { return state.bookmarks.indexOf(m.id) !== -1; });
    var historyItems = state.history.map(function (h) {
      var m = state.data.manga.filter(function (x) { return x.id === h.mangaId; })[0];
      return m ? { manga: m, history: h } : null;
    }).filter(Boolean);
    var myComments = state.data.comments.filter(function (c) { return state.user && c.userId === state.user.id; }).length;
    var komikDibaca = historyItems.length;
    var chapterSelesai = historyItems.length;

    if (!state.user) {
      var guestLogo = siteLogo();
      var brandMedia = guestLogo
        ? '<div class="kv-login-brand-logo"><img src="' + escapeHtml(guestLogo) + '" alt="Logo ' + escapeHtml(siteName()) + '"/></div>'
        : '';
      var checkIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="20 6 9 17 4 10"></polyline></svg>';
      var guestFeatures = [
        'Simpan manga favorit ke bookmark',
        'Lanjutkan bacaan dari chapter terakhir',
        'Ikut berdiskusi di komentar tiap judul'
      ].map(function (text) {
        return '<li><span class="kv-login-feature-icon">' + checkIcon + '</span><span>' + escapeHtml(text) + '</span></li>';
      }).join('');
      return '<main class="kv-container kv-home-light kv-account-page">' +
        '<section class="kv-login-shell">' +
          '<div class="kv-login-brand">' +
            brandMedia +
            '<span class="kv-login-kicker">' + escapeHtml(siteName()) + '</span>' +
            '<h1 class="kv-login-title">Selamat datang di ' + escapeHtml(siteName()) + '</h1>' +
            '<p class="kv-login-sub">Masuk untuk membuka semua fitur pembaca — dari favorit hingga komentar. Satu akun untuk semua, tanpa password tambahan.</p>' +
            '<ul class="kv-login-features">' + guestFeatures + '</ul>' +
          '</div>' +
          '<div class="kv-login-card">' +
            '<h2 class="kv-login-card-title">Masuk ke akunmu</h2>' +
            '<p class="kv-login-card-sub">Pilih penyedia akun. Kamu akan diarahkan sebentar ke halaman resmi Google atau Discord lalu kembali ke sini.</p>' +
            '<div class="kv-login-providers">' + renderOAuthButtons() + '</div>' +
            '<p class="kv-login-foot">Masuk menggunakan akun Google atau Discord. Kata sandi dikelola sepenuhnya oleh penyedia layanan tersebut dan tidak disimpan maupun diakses oleh sistem kami.</p>' +
          '</div>' +
        '</section>' +
      '</main>';
    }

    var override = profileOverride();
    var displayName = String(override.name || state.user.name || 'Member');
    var displayAvatar = override.avatar || state.user.avatar || '';
    var initial = escapeHtml(displayName.charAt(0).toUpperCase());
    var avatar = displayAvatar
      ? '<img src="' + escapeHtml(displayAvatar) + '" alt="Avatar ' + escapeHtml(displayName) + '" class="kv-account-avatar-img" referrerpolicy="no-referrer"/>'
      : '<div class="kv-account-avatar-fallback">' + initial + '</div>';
    var roleLabel = state.user.role === 'admin' ? 'Administrator' : 'Pembaca';

    return '<main class="kv-container kv-home-light kv-account-page">' +
      '<section class="kv-account-hero">' +
        '<div class="kv-account-banner">' +
          '<div class="kv-account-banner-badge"><span class="kv-account-pulse"></span>Aktif</div>' +
        '</div>' +
        '<div class="kv-account-identity">' +
          '<div class="kv-account-avatar-wrap">' + avatar + '</div>' +
          '<div class="kv-account-bio">' +
            '<div class="kv-account-name-row">' +
              '<h1>' + escapeHtml(displayName) + '</h1>' +
              '<span class="kv-account-role">' + escapeHtml(roleLabel) + '</span>' +
            '</div>' +
            '<p class="kv-account-handle">' + escapeHtml(state.user.email || state.user.provider || 'member') + '</p>' +
            '<p class="kv-account-meta">Melalui ' + escapeHtml(state.user.provider) + ' &middot; Role: ' + escapeHtml(state.user.role) + '</p>' +
          '</div>' +
          '<div class="kv-account-actions">' +
            '<button type="button" class="kv-account-secondary" data-action="toggle-edit-profile">Edit Profil</button>' +
            '<button type="button" class="kv-account-primary" data-action="logout-user">Keluar</button>' +
          '</div>' +
        '</div>' +
        '<div class="kv-account-metrics">' +
          '<div class="kv-account-metric"><span class="kv-account-metric-label">Komik Dibaca</span><span class="kv-account-metric-value">' + komikDibaca + '</span></div>' +
          '<div class="kv-account-metric"><span class="kv-account-metric-label">Chapter Selesai</span><span class="kv-account-metric-value">' + chapterSelesai + '</span></div>' +
          '<div class="kv-account-metric"><span class="kv-account-metric-label">Bookmark Aktif</span><span class="kv-account-metric-value">' + favManga.length + '</span></div>' +
          '<div class="kv-account-metric"><span class="kv-account-metric-label">Komentar Saya</span><span class="kv-account-metric-value">' + myComments + '</span></div>' +
        '</div>' +
      '</section>' +
      (state.editingProfile
        ? '<form id="kv-profile-form" class="kv-account-edit">' +
            '<div class="kv-account-edit-head">' +
              '<div class="kv-account-block-title">Edit Profil</div>' +
              '<button type="button" class="kv-account-pref-btn" data-action="toggle-edit-profile">Batal</button>' +
            '</div>' +
            '<div class="kv-account-edit-grid">' +
              '<label class="kv-account-edit-label">Nama Tampilan<input class="kv-input" name="name" type="text" value="' + escapeHtml(displayName) + '" required/></label>' +
              '<label class="kv-account-edit-label">URL Avatar<input class="kv-input" name="avatar" type="url" value="' + escapeHtml(displayAvatar) + '" placeholder="https://..."/></label>' +
            '</div>' +
            '<p class="kv-account-edit-hint">Disimpan di browser ini. Tidak mengubah data akun di server OAuth.</p>' +
            '<div class="kv-account-edit-actions">' +
              '<button type="submit" class="kv-account-primary">Simpan Profil</button>' +
            '</div>' +
          '</form>'
        : '') +
      '<div class="kv-account-layout">' +
        '<div class="kv-account-main">' +
          '<section class="kv-account-block">' +
            '<div class="kv-account-block-head">' +
              '<div class="kv-account-block-title"><span class="kv-account-dot kv-account-dot-primary"></span>Lanjutkan Membaca</div>' +
              '<span class="kv-account-block-note">' + historyItems.length + ' judul</span>' +
            '</div>' +
            (historyItems.length
              ? historyItems.slice(0, 4).map(function (item) {
                  var m = item.manga; var h = item.history;
                  return '<article class="kv-account-history-card">' +
                    '<div class="kv-account-history-cover"><img src="' + escapeHtml(m.coverBloggerUrl || '') + '" alt="' + escapeHtml(m.title) + '" loading="lazy" referrerpolicy="no-referrer"/></div>' +
                    '<div class="kv-account-history-body">' +
                      '<span class="kv-account-history-type">' + escapeHtml(m.type || 'Manga') + '</span>' +
                      '<h3>' + escapeHtml(m.title) + '</h3>' +
                      '<div class="kv-account-history-meta"><span>Terakhir dibaca: Chapter ' + escapeHtml(h.chapterNumber) + '</span><span>&middot;</span><span>' + escapeHtml(h.lastReadAt || '') + '</span></div>' +
                      '<a class="kv-account-history-btn" href="#/baca/' + escapeHtml(m.slug) + '/' + escapeHtml(h.chapterId) + '">Lanjut Baca Ch. ' + escapeHtml(h.chapterNumber) + ' &rarr;</a>' +
                    '</div>' +
                  '</article>';
                }).join('')
              : '<p class="kv-account-empty">Belum ada riwayat baca. Mulai membaca manga untuk melihatnya di sini.</p>') +
          '</section>' +
          '<section class="kv-account-block">' +
            '<div class="kv-account-block-head">' +
              '<div class="kv-account-block-title"><span class="kv-account-dot kv-account-dot-secondary"></span>Koleksi Bookmark</div>' +
              '<a class="kv-account-block-note kv-account-link" href="#/archive">Archive &rarr;</a>' +
            '</div>' +
            (favManga.length
              ? '<div class="kv-home-grid kv-account-fav-grid">' + favManga.slice(0, 8).map(renderLightCard).join('') + '</div>'
              : '<p class="kv-account-empty">Belum ada manga yang disimpan. Tandai favorit dari halaman detail manga.</p>') +
          '</section>' +
        '</div>' +
        '<aside class="kv-account-sidebar">' +
          '<section class="kv-account-side-card">' +
            '<div class="kv-account-block-title">Preferensi Membaca</div>' +
            '<div class="kv-account-pref-row">' +
              '<span class="kv-account-pref-icon">☰</span>' +
              '<div><strong>Gaya Pembaca</strong><p>' + (state.readerMode === 'vertical' ? 'Webtoon scroll' : 'Halaman tunggal') + '</p></div>' +
              '<button type="button" class="kv-account-pref-btn" data-action="toggle-reader-mode">Ubah</button>' +
            '</div>' +
          '</section>' +
          '<section class="kv-account-side-card">' +
            '<div class="kv-account-block-title">Pintasan</div>' +
            '<div class="kv-account-links">' +
              '<a href="#/archive">Archive &rarr;</a>' +
              '<a href="#/tentang">Tentang NexaManga &rarr;</a>' +
              '<a href="#/ketentuan">Ketentuan Layanan &rarr;</a>' +
            '</div>' +
          '</section>' +
          '<button type="button" class="kv-account-logout" data-action="logout-user">Keluar dari Akun</button>' +
        '</aside>' +
      '</div>' +
    '</main>';
  }

  function renderOAuthButtons() {
    if (!CONFIG.API_BASE_URL) {
      return '<p style="color:var(--kv-text-muted);font-size:0.875rem;">Login membutuhkan backend Vercel. Atur API_BASE_URL untuk mengaktifkan Google dan Discord.</p>';
    }
    var googleIcon = '<svg viewBox="0 0 48 48" aria-hidden="true">' +
      '<path fill="#FFC107" d="M43.6 20.5H42V20H24v8h11.3C33.7 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.9 1.2 8 3l5.7-5.7C34 6.1 29.3 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.2-.1-2.3-.4-3.5z"/>' +
      '<path fill="#FF3D00" d="M6.3 14.7l6.6 4.8C14.6 15.9 18.9 12 24 12c3.1 0 5.9 1.2 8 3l5.7-5.7C34 6.1 29.3 4 24 4 16.3 4 9.7 8.4 6.3 14.7z"/>' +
      '<path fill="#4CAF50" d="M24 44c5.2 0 10-2 13.5-5.2l-6.2-5.2C29.3 35.4 26.8 36 24 36c-5.2 0-9.7-3.3-11.3-8l-6.5 5C9.5 39.5 16.2 44 24 44z"/>' +
      '<path fill="#1976D2" d="M43.6 20.5H42V20H24v8h11.3c-.8 2.2-2.2 4.2-4 5.9l6.2 5.2C37.3 39.5 44 34 44 24c0-1.2-.1-2.3-.4-3.5z"/>' +
    '</svg>';
    var discordIcon = '<svg viewBox="0 0 24 24" fill="#FFFFFF" aria-hidden="true">' +
      '<path d="M20.3 4.4A19.9 19.9 0 0 0 15.4 3c-.2.4-.4.8-.6 1.2a18.4 18.4 0 0 0-5.6 0A12.6 12.6 0 0 0 8.6 3a19.9 19.9 0 0 0-4.9 1.4C.7 8.7.1 13 .6 17.1a19.9 19.9 0 0 0 6 2.9c.5-.6.9-1.3 1.3-2a13 13 0 0 1-2-1l.5-.4a14.2 14.2 0 0 0 12.2 0l.5.4a13 13 0 0 1-2 1c.4.7.8 1.4 1.3 2a19.8 19.8 0 0 0 6-2.9c.6-4.7-1.1-9-3.7-12.7zM9.7 13.6c-1.1 0-2-1-2-2.3s.9-2.3 2-2.3 2 1 2 2.3-.9 2.3-2 2.3zm4.6 0c-1.1 0-2-1-2-2.3s.9-2.3 2-2.3 2 1 2 2.3-.9 2.3-2 2.3z"/>' +
    '</svg>';
    return '<button type="button" class="kv-login-btn kv-login-btn-google" data-action="oauth-login" data-provider="google">' + googleIcon + '<span>Lanjutkan dengan Google</span></button>' +
      '<button type="button" class="kv-login-btn kv-login-btn-discord" data-action="oauth-login" data-provider="discord">' + discordIcon + '<span>Lanjutkan dengan Discord</span></button>';
  }

  function renderAdmin() {
    if (!state.adminToken || !state.user || state.user.role !== 'admin') {
      return render404();
    }
    var tab = state.adminTab || 'dashboard';
    var pending = state.data.comments.filter(function (c) { return c.status === 'pending'; }).length;
    var body;
     if (tab === 'manga') {
      if (state.adminChapterForm) body = renderAdminChapterForm();
      else if (state.adminForm) body = renderAdminMangaForm();
      else if (state.adminChapterFullId) body = renderAdminChapterList();
      else body = renderAdminMangaList();

     }
      else if (tab === 'komentar') body = renderAdminComments();
      else if (tab === 'analytics') body = renderAdminAnalytics();
      else if (tab === 'leaderboard') body = renderAdminLeaderboard();
      else if (tab === 'pengguna') body = renderAdminUsers();
      else if (tab === 'pengaturan') body = renderAdminSettings();
      else body = renderAdminDashboard();


     var titles = {
       dashboard: ['Dashboard Analitik', 'KPI, grafik, dan pintasan cepat.'],
       manga: ['Manajemen Manga & Chapter', 'Tambah, ubah, hapus manga dan kelola chapter per judul.'],
        komentar: ['Moderasi Komentar', 'Setujui, tolak, atau hapus komentar pembaca.'],
        analytics: ['Analitik Traffic', 'Rincian traffic situs dari awal bulan ini sampai hari ini.'],
        leaderboard: ['Leaderboard Judul', 'Semua judul diurutkan berdasarkan jumlah pembaca.'],
       pengguna: ['Manajemen Pengguna', 'Daftar akun, ubah role, dan hapus pengguna.'],
       pengaturan: ['Pengaturan', 'Konfigurasi tema, integrasi backend, dan zona bahaya.']
     };
    var t = titles[tab] || titles.dashboard;
    var topActions;
    if (tab === 'dashboard') {
      topActions = '<a class="kv-btn kv-btn-ghost" href="#/">Lihat Situs</a>' +
        '<button type="button" class="kv-btn kv-btn-ghost" data-action="admin-new-chapter">+ Chapter</button>' +
        '<button type="button" class="kv-btn kv-btn-primary" data-action="admin-new-manga">+ Manga</button>';
     } else if (tab === 'manga') {
       topActions = '<a class="kv-btn kv-btn-ghost" href="#/archive">Buka Archive</a>' +
         (state.adminForm || state.adminChapterForm
           ? '<button type="button" class="kv-btn kv-btn-ghost" data-action="admin-cancel-form">Batal Edit</button>'
           : '<button type="button" class="kv-btn kv-btn-primary" data-action="admin-new-manga">+ Tambah Manga</button>');
     } else if (tab === 'komentar') {
      topActions = '<a class="kv-btn kv-btn-ghost" href="#/">Lihat Situs</a>';
    } else {
      topActions = '<a class="kv-btn kv-btn-ghost" href="#/">Lihat Situs</a>';
    }

     var navMain = [
        { key: 'dashboard', label: 'Dashboard', icon: 'grid' },
        { key: 'analytics', label: 'Analitik', icon: 'trend' },
        { key: 'manga', label: 'Manga', icon: 'book' },

        { key: 'komentar', label: 'Komentar', icon: 'chat', badge: pending },
        { key: 'leaderboard', label: 'Leaderboard', icon: 'trend' },
        { key: 'pengguna', label: 'Pengguna', icon: 'users' },

       { key: 'pengaturan', label: 'Pengaturan', icon: 'gear' }
     ];
    var navHtml = navMain.map(function (n) {
      return '<button type="button" class="kv-admin-nav-item' + (tab === n.key ? ' active' : '') + '" role="tab" aria-selected="' + (tab === n.key ? 'true' : 'false') + '" data-action="admin-tab" data-tab="' + n.key + '">' +
        kvIcon(n.icon) + '<span>' + n.label + '</span>' +
        (n.badge ? '<span class="kv-admin-nav-badge">' + n.badge + '</span>' : '') +
      '</button>';
    }).join('');
    var adminBrandMode = brandMode();
    var adminBrandIcon = adminBrandMode !== 'name-only'
      ? (siteLogo()
        ? '<span class="kv-admin-logo-icon"><img src="' + escapeHtml(siteLogo()) + '" alt="Logo"/></span>'
        : '<span class="kv-admin-logo-icon">' + kvIcon('book') + '</span>')
      : '';
    var adminBrandText = adminBrandMode !== 'logo-only'
      ? '<a class="kv-admin-logo" href="#/"><span' + siteNameStyle() + '>' + escapeHtml(siteName()) + '</span> <span>Console</span></a>'
      : '';

     var quickHtml = [
       { label: 'Tambah Manga', icon: 'plus', act: 'admin-new-manga' },
       { label: 'Tambah Chapter', icon: 'layers', act: 'admin-new-chapter' }
     ].map(function (n) {
      return '<button type="button" class="kv-admin-nav-item" data-action="' + n.act + '"' + (n.tab ? ' data-tab="' + n.tab + '"' : '') + '>' + kvIcon(n.icon) + '<span>' + n.label + '</span></button>';
    }).join('');

      return '<div class="kv-admin-shell kv-admin-top' + (state.adminDrawerOpen ? ' kv-admin-drawer-open' : '') + '">' +
        '<aside class="kv-admin-sidebar">' +
          '<div class="kv-admin-brand">' +
            '<div class="kv-admin-brand-row">' +
              adminBrandIcon +
              adminBrandText +
            '</div>' +
            '<div class="kv-admin-chip' + (CONFIG.API_BASE_URL ? '' : ' off') + '"><span class="dot"></span><span>' + (CONFIG.API_BASE_URL ? 'Backend terhubung' : 'Mode lokal') + '</span></div>' +
          '</div>' +
          '<div class="kv-admin-side-group">' +
            '<div class="kv-admin-side-label">Core Modules</div>' +
            '<nav class="kv-admin-nav" aria-label="Menu panel admin">' + navHtml + '</nav>' +
          '</div>' +
          '<div class="kv-admin-side-group">' +
            '<div class="kv-admin-side-label">Engine &amp; Delivery</div>' +
            '<div class="kv-admin-side-quick">' + quickHtml + '</div>' +
          '</div>' +
          '<div class="kv-admin-side-foot">' +
            '<a class="kv-admin-quicklink" href="#/">' + kvIcon('globe') + ' Lihat Situs</a>' +
            '<a class="kv-admin-quicklink" href="#/archive">' + kvIcon('book') + ' Archive</a>' +
            '<a class="kv-admin-quicklink" href="#/akun">' + kvIcon('users') + ' Pustaka</a>' +
          '</div>' +
        '</aside>' +
        '<div class="kv-admin-content">' +
          '<header class="kv-admin-topbar kv-admin-topbar-new">' +
            '<button type="button" class="kv-admin-hamburger" data-action="toggle-admin-drawer" aria-label="Buka menu admin" aria-expanded="' + (state.adminDrawerOpen ? 'true' : 'false') + '"><span class="material-symbols-outlined">menu</span></button>' +

            '<div class="kv-admin-top-actions">' +
              '<a class="kv-admin-avatar" href="#/akun" aria-label="Akun saya">' + (state.user.avatar ? '<img src="' + escapeHtml(state.user.avatar) + '" alt=""/>' : escapeHtml(String(state.user.name || 'A').charAt(0).toUpperCase())) + '</a>' +
              '<button type="button" class="kv-btn kv-btn-ghost" data-action="logout-admin">' + kvIcon('out') + ' Keluar</button>' +
            '</div>' +
          '</header>' +
          '<main class="kv-admin-main kv-admin-main-full">' +
            '<div class="kv-admin-pagehead">' +
              '<div><h1 class="kv-admin-title">' + t[0] + '</h1><p class="kv-admin-sub">' + t[1] + '</p></div>' +
              '<div class="kv-admin-top-actions">' + topActions + '</div>' +
            '</div>' +
             body +
           '</main>' +

        '</div>' +
        (state.adminDrawerOpen ? '<div class="kv-admin-overlay" data-action="close-admin-drawer" aria-hidden="true"></div>' : '') +
      '</div>';
  }

  function renderAdminDashboard() {
    var pending = state.data.comments.filter(function (c) { return c.status === 'pending'; }).length;
    var totalViews = state.data.manga.reduce(function (acc, m) { return acc + (m.views || 0); }, 0);
    var totalUsers = (state.usersCache || []).length;
    var kpis =
      '<div class="kv-kpi"><div class="ico">' + kvIcon('book') + '</div><div class="lbl">Total Manga</div><div class="val">' + state.data.manga.length + '</div><div class="delta">Judul terdaftar</div></div>' +
      '<div class="kv-kpi"><div class="ico">' + kvIcon('layers') + '</div><div class="lbl">Total Chapter</div><div class="val">' + state.data.chapters.length + '</div><div class="delta">Halaman tersimpan</div></div>' +
      '<div class="kv-kpi"><div class="ico">' + kvIcon('chat') + '</div><div class="lbl">Komentar Menunggu</div><div class="val">' + pending + '</div><div class="delta">Perlu moderasi</div></div>' +
      '<div class="kv-kpi"><div class="ico">' + kvIcon('trend') + '</div><div class="lbl">Total Dibaca</div><div class="val">' + totalViews.toLocaleString('id-ID') + '</div><div class="delta">Akumulasi views</div></div>';
    // Bar chart: views per manga (top 8)
    var counts = state.data.manga.map(function (m) {
      return { title: m.title, count: m.views || 0 };
    }).sort(function (a, b) { return b.count - a.count; }).slice(0, 8);
    var maxC = counts.reduce(function (a, c) { return Math.max(a, c.count); }, 1) || 1;
    var bars = counts.map(function (c) {
      var h = Math.round((c.count / maxC) * 150);
      return '<div class="kv-bar-col">' +
        '<div class="kv-bar-val">' + c.count.toLocaleString('id-ID') + '</div>' +
        '<div class="kv-bar" style="height:' + h + 'px;" title="' + escapeHtml(c.title) + ': ' + c.count.toLocaleString('id-ID') + ' views"></div>' +
        '<div class="kv-bar-label">' + escapeHtml(c.title) + '</div>' +
      '</div>';
    }).join('');
     var chart = '<div class="kv-chart-card"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px;"><h3 class="kv-chart-title" style="margin:0;">View per Manga</h3><button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-open-leaderboard">Lihat Semua &rarr;</button></div><p class="kv-chart-sub">Top 8 manga berdasarkan jumlah pembaca.</p>' +
       (bars ? '<div class="kv-bar-chart">' + bars + '</div>' : '<p style="color:var(--kv-text-muted);">Belum ada data.</p>') + '</div>';

    var qas = [
      { icon: 'plus', t: 'Tambah Manga', d: 'Publikasikan judul baru ke archive.', act: 'admin-new-manga' },
      { icon: 'layers', t: 'Tambah Chapter', d: 'Unggah halaman ke penyimpanan Telegram.', act: 'admin-new-chapter' },
      { icon: 'chat', t: 'Moderasi Komentar', d: pending + ' komentar menunggu review.', act: 'admin-tab', tab: 'komentar' },
      { icon: 'book', t: 'Kelola Manga', d: 'Ubah metadata, unggulan & rekomendasi.', act: 'admin-tab', tab: 'manga' },
      { icon: 'eye', t: 'Kelola Chapter', d: 'Urutan, progres gambar, dan preview.', act: 'admin-tab', tab: 'chapter' },
      { icon: 'gear', t: 'Pengaturan', d: 'Konfigurasi integrasi & data.', act: 'admin-tab', tab: 'pengaturan' }
    ].map(function (q) {
      return '<button type="button" class="kv-qa" data-action="' + q.act + '"' + (q.tab ? ' data-tab="' + q.tab + '"' : '') + '>' +
        '<span class="kv-qa-ico">' + kvIcon(q.icon) + '</span>' +
        '<span><span class="kv-qa-title">' + q.t + '</span><span class="kv-qa-desc">' + q.d + '</span></span>' +
      '</button>';
    }).join('');

     return '<div class="kv-kpi-grid">' + kpis + '</div>' +
       '<div class="kv-two-col">' + chart +
         '<div class="kv-card"><h3>Aksi Cepat</h3><div class="kv-qa-grid">' + qas + '</div></div>' +
       '</div>' +
       '</div>';
   }


    function renderAdminLeaderboard() {
      var sorted = state.data.manga.slice().sort(function (a, b) { return (b.views || 0) - (a.views || 0); });
      var maxV = sorted.reduce(function (a, m) { return Math.max(a, m.views || 0); }, 1) || 1;
      var rows = sorted.map(function (m, i) {
        var v = m.views || 0;
        var w = Math.round((v / maxV) * 100);
        var chs = state.data.chapters.filter(function (c) { return c.mangaId === m.id; }).length;
        return '<div class="kv-admin-leader-row">' +
          '<div class="kv-admin-leader-rank">' + (i + 1) + '</div>' +
          '<div class="kv-admin-leader-cover">' + renderCover(m.coverBloggerUrl, m.title) + '</div>' +
          '<div class="kv-admin-leader-body">' +
            '<div class="kv-admin-leader-title">' + escapeHtml(m.title) + '</div>' +
            '<div class="kv-admin-leader-meta">' + escapeHtml(m.type || 'Manga') + ' · ' + escapeHtml(m.status || 'Ongoing') + ' · ' + chs + ' chapter' + (m.rating ? ' · ★ ' + escapeHtml(m.rating) : '') + '</div>' +
            '<div class="kv-admin-leader-barwrap"><div class="kv-admin-leader-bar" style="width:' + w + '%;"></div></div>' +
          '</div>' +
          '<div class="kv-admin-leader-views">' + v.toLocaleString('id-ID') + ' <span>views</span></div>' +
          '<div class="kv-admin-leader-actions">' +
            '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-preview-manga" data-slug="' + escapeHtml(m.slug) + '">Preview</button>' +
            '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-edit-manga" data-id="' + escapeHtml(m.id) + '">Ubah</button>' +
          '</div>' +
        '</div>';
      }).join('');
      return '<div class="kv-card">' +
        '<div class="kv-toolbar" style="justify-content:space-between;align-items:center;">' +
          '<h3 style="margin:0;">Leaderboard Semua Judul</h3>' +
          '<button type="button" class="kv-btn kv-btn-ghost" data-action="admin-tab" data-tab="dashboard">Kembali ke Dashboard</button>' +
        '</div>' +
        '<p style="color:var(--kv-text-muted);font-size:0.8125rem;margin:8px 0 16px;">' + sorted.length + ' judul, diurutkan dari views tertinggi ke terendah.</p>' +
        (rows ? '<div class="kv-admin-leader-list">' + rows + '</div>' : '<p class="kv-admin-empty">Belum ada manga.</p>') +
      '</div>';
    }

    function renderAdminAnalytics() {
      var now = new Date();
      var toStr = now.toISOString().slice(0, 10);
      var fromStr = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0') + '-01';
      if (!state.analyticsFrom) state.analyticsFrom = fromStr;
      if (!state.analyticsTo) state.analyticsTo = toStr;
      fromStr = state.analyticsFrom;
      toStr = state.analyticsTo;
      if (state.analyticsData === undefined) {
        state.analyticsData = null;
        loadAdminAnalytics(fromStr, toStr);
        return '<div class="kv-card" style="margin-top:16px;"><p style="color:var(--kv-text-muted);">Memuat analitik...</p></div>';
      }
      var d = state.analyticsData || {};
      var t = (d.totals) || { pageviews: 0, visitors: 0, visits: 0, average: 0 };
      return '<div class="kv-card" style="margin-bottom:16px;">' +
        '<h3 class="kv-section-title" style="margin:0 0 8px;">Analitik Traffic</h3>' +
        '<p style="color:var(--kv-text-muted);font-size:0.85rem;margin:0 0 12px;">Halaman ini menampilkan rincian traffic situs. Tanggal otomatis dari awal bulan ini sampai hari ini. Ubah rentang tanggal lalu tekan Refresh.</p>' +
        '</div>' +
        '<section class="kv-traffic">' +
          '<div class="kv-traffic-toolbar">' +
            '<div class="kv-traffic-field"><label>DARI</label><input type="date" id="kv-traffic-from" value="' + fromStr + '"/></div>' +
            '<div class="kv-traffic-field"><label>SAMPAI</label><input type="date" id="kv-traffic-to" value="' + toStr + '"/></div>' +
            '<button type="button" class="kv-btn kv-btn-primary" data-action="kv-traffic-refresh">&#8635; Refresh</button>' +
          '</div>' +
          '<div class="kv-traffic-cards">' +
            '<article class="kv-traffic-card"><div class="kv-traffic-label">TOTAL PAGEVIEWS</div><div class="kv-traffic-value" id="kv-traffic-pageviews">' + (t.pageviews || 0).toLocaleString('id-ID') + '</div><div class="kv-traffic-note" id="kv-traffic-period">Period: ' + fromStr + ' to ' + toStr + '</div></article>' +
            '<article class="kv-traffic-card"><div class="kv-traffic-label">UNIQUE VISITORS</div><div class="kv-traffic-value" id="kv-traffic-visitors">' + (t.visitors || 0).toLocaleString('id-ID') + '</div><div class="kv-traffic-note">Distinct visitor hashes</div></article>' +
            '<article class="kv-traffic-card"><div class="kv-traffic-label">TOTAL VISITS</div><div class="kv-traffic-value" id="kv-traffic-visits">' + (t.visits || 0).toLocaleString('id-ID') + '</div><div class="kv-traffic-note">Session-based estimate</div></article>' +
            '<article class="kv-traffic-card"><div class="kv-traffic-label">AVG. PAGES/VISIT</div><div class="kv-traffic-value" id="kv-traffic-average">' + (t.average || 0) + '</div><div class="kv-traffic-note">Engagement metric</div></article>' +
          '</div>' +
             '<div class="kv-traffic-chart">' +
             '<h3 class="kv-chart-title">&#9635; Traffic Overview</h3>' +
             '<p class="kv-chart-sub">Pageviews, visitors, and visits over time</p>' +
             '<div class="kv-traffic-legend"><span><i class="kv-traffic-dot" style="background:#62a5ff"></i>Pageviews</span><span><i class="kv-traffic-dot" style="background:#d77aa9"></i>Unique Visitors</span><span><i class="kv-traffic-dot" style="background:#e6d36f"></i>Visits</span></div>' +
             (function () {
               var daily = (d.daily && d.daily.length) ? d.daily : [];
               if (!daily.length) return '<p style="color:var(--kv-text-muted);text-align:center;padding:24px 0;">Belum ada data traffic pada rentang ini.</p>';
               var maxV = 1;
               daily.forEach(function (r) { maxV = Math.max(maxV, r.pageviews || 0, r.visitors || 0, r.visits || 0); });
               var left = 55, right = 1080, top = 35, bottom = 275;
               var span = right - left;
               var range = bottom - top;
               function x(i) { return daily.length === 1 ? (left + right) / 2 : left + (i * span) / (daily.length - 1); }
               function y(v) { return bottom - ((v || 0) / maxV) * range; }
               function path(key, color) {
                 var pts = daily.map(function (r, i) { return x(i) + ',' + y(r[key]); }).join(' ');
                 return '<polyline points="' + pts + '" class="kv-traffic-line" stroke="' + color + '" fill="none"><title>' + key + '</title></polyline>';
               }
               var labels = daily.map(function (r, i) {
                 var dt = String(r.date || '');
                 var short = dt.length >= 10 ? dt.slice(8, 10) + ' ' + ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'][parseInt(dt.slice(5, 7), 10) - 1] : dt;
                 return '<text class="kv-traffic-axis" x="' + x(i) + '" y="302" text-anchor="middle">' + short + '</text>';
               }).join('');
               var yLabels = [0, 0.25, 0.5, 0.75, 1].map(function (f) {
                 var v = Math.round(maxV * f);
                 return '<text class="kv-traffic-axis" x="38" y="' + (bottom - f * range + 4) + '">' + v + '</text>' +
                   '<line class="kv-traffic-grid" x1="55" y1="' + (bottom - f * range) + '" x2="1080" y2="' + (bottom - f * range) + '"/>';
               }).join('');
               return '<svg viewBox="0 0 1100 355" role="img" aria-label="Grafik traffic"><title>Traffic Overview</title>' +
                 yLabels +
                 path('pageviews', '#62a5ff') +
                 path('visitors', '#d77aa9') +
                 path('visits', '#e6d36f') +
                 '<g text-anchor="middle">' + labels + '</g>' +
                 '</svg>';
             })() +
           '</div>' +
         '</section>';

    }

    function renderAdminMangaList() {
     var q = state.adminSearch.toLowerCase();
     var list = state.data.manga.filter(function (m) {
       return !q || m.title.toLowerCase().indexOf(q) !== -1 || m.slug.indexOf(q) !== -1;
     });
     var cards = list.map(function (m) {
       var chs = state.data.chapters.filter(function (c) { return c.mangaId === m.id; });
       var expanded = state.adminExpandedManga === m.id;
       return '<div class="kv-manga-card">' +
         '<div class="kv-manga-card-cover">' + renderCover(m.coverBloggerUrl, m.title) + '</div>' +
         '<div class="kv-manga-card-body">' +
           '<div class="kv-manga-card-head">' +
             '<div><h3 class="kv-manga-card-title">' + escapeHtml(m.title) + '</h3>' +
               '<div class="kv-mono kv-manga-card-slug">' + escapeHtml(m.slug) + '</div></div>' +
             '<div class="kv-manga-card-badges">' + (m.featured ? '<span class="kv-badge kv-badge-ok">Unggulan</span> ' : '') + (m.recommended ? '<span class="kv-badge">Rekomendasi</span>' : '') + '</div>' +
           '</div>' +
           '<div class="kv-manga-card-meta">' +
             '<span>' + escapeHtml(m.type) + '</span><span class="dot">·</span>' +
             '<span>' + escapeHtml(m.status) + '</span><span class="dot">·</span>' +
             '<span>' + chs.length + ' chapter</span>' +
             (m.rating ? '<span class="dot">·</span><span>★ ' + escapeHtml(m.rating) + '</span>' : '') +
           '</div>' +
           '<div class="kv-manga-card-actions">' +
             '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-toggle-expand" data-id="' + escapeHtml(m.id) + '">' + kvIcon('chev') + ' ' + (expanded ? 'Tutup' : 'Chapter') + '</button>' +
             '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-edit-manga" data-id="' + escapeHtml(m.id) + '">Ubah</button>' +
             '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-preview-manga" data-slug="' + escapeHtml(m.slug) + '">Preview</button>' +
             '<button type="button" class="kv-btn kv-btn-sm kv-btn-danger-ghost" data-action="admin-delete-manga" data-id="' + escapeHtml(m.id) + '">Hapus</button>' +
           '</div>' +
         '</div>' +
       '</div>' +
       (expanded ? '<div class="kv-manga-card-panel">' + renderAdminChapterPanel(m, chs) + '</div>' : '');
     }).join('');
     return '<div class="kv-card" style="margin-bottom:16px;">' +
       '<div class="kv-toolbar">' +
         '<input id="kv-admin-manga-search" class="kv-input" type="search" placeholder="Cari judul atau slug..." value="' + escapeHtml(state.adminSearch) + '" aria-label="Cari manga di panel admin"/>' +
         '<button type="button" class="kv-btn kv-btn-primary" data-action="admin-new-manga">+ Tambah Manga</button>' +
       '</div>' +
       (cards ? '<div class="kv-manga-grid">' + cards + '</div>' : '<p style="text-align:center;color:var(--kv-text-muted);padding:24px 0;">Tidak ada manga.</p>') +
     '</div>';
   }

  /* Panel chapter terintegrasi di baris manga — selalu diurut otomatis by nomor */
  function renderAdminChapterPanel(m, chs) {
    var sorted = chs.slice().sort(function (a, b) { return a.number - b.number; });
    var rows = sorted.map(function (c) {
      var uploaded = c.pages.filter(function (p) { return p.bloggerUrl; }).length;
      return '<div class="kv-admin-chapter-row">' +
        '<div class="kv-admin-chapter-info">' +
          '<span class="kv-badge kv-mono">Ch. ' + c.number + '</span>' +
          '<span class="kv-admin-chapter-title">' + escapeHtml(c.title || '(tanpa judul)') + '</span>' +
          '<span class="kv-mono kv-admin-chapter-meta">' + uploaded + '/' + c.pages.length + ' img</span>' +
        '</div>' +
        '<div class="kv-admin-chapter-actions">' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-edit-chapter" data-id="' + escapeHtml(c.id) + '">Ubah</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-preview-chapter" data-slug="' + escapeHtml(m.slug) + '" data-cid="' + escapeHtml(c.id) + '">Preview</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-danger-ghost" data-action="admin-delete-chapter" data-id="' + escapeHtml(c.id) + '">Hapus</button>' +
        '</div>' +
      '</div>';
    }).join('');
    return '<div class="kv-admin-chapter-panel">' +
      '<div class="kv-admin-chapter-head">' +
        '<div class="kv-admin-chapter-heading">' +
          '<strong>Chapter &mdash; ' + escapeHtml(m.title) + '</strong>' +
          '<span class="kv-admin-chapter-sub">' + sorted.length + ' chapter &middot; diurutkan otomatis berdasarkan nomor</span>' +
        '</div>' +
        '<div class="kv-admin-chapter-head-actions">' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-primary" data-action="admin-new-chapter" data-id="' + escapeHtml(m.id) + '">+ Tambah Chapter</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-open-chapters" data-id="' + escapeHtml(m.id) + '">Kelola Penuh</button>' +
        '</div>' +
      '</div>' +
      (rows || '<p class="kv-admin-chapter-empty">Belum ada chapter. Nomor pertama akan disarankan otomatis saat menambah.</p>') +
    '</div>';
  }

  function renderAdminMangaForm() {
    var f = state.adminForm;
     return '<form id="kv-manga-form" class="kv-card" style="margin-top:16px;" novalidate>' +
      '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:14px;">' +
        '<h2 class="kv-section-title">' + (f.id ? 'Ubah Manga' : 'Tambah Manga Baru') + '</h2>' +
        '<button type="button" class="kv-btn kv-btn-ghost" data-action="admin-cancel-form">Batal</button>' +
      '</div>' +
      '<input type="hidden" name="id" value="' + escapeHtml(f.id || '') + '"/>' +
      '<div class="kv-form-grid">' +
        '<label>Judul *<input class="kv-input" name="title" value="' + escapeHtml(f.title) + '" required style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Judul Alternatif<input class="kv-input" name="altTitle" value="' + escapeHtml(f.altTitle || '') + '" style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Slug (otomatis dari judul jika kosong)<input class="kv-input kv-mono" name="slug" value="' + escapeHtml(f.slug || '') + '" placeholder="contoh: judul-manga" style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Penulis<input class="kv-input" name="author" value="' + escapeHtml(f.author || '') + '" style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label style="grid-column:1/-1;">Sinopsis *' +
          '<div class="kv-toolbar-wysi">' +
            '<button type="button" data-wysi="bold">B</button>' +
            '<button type="button" data-wysi="italic">I</button>' +
            '<button type="button" data-wysi="h3">H3</button>' +
            '<button type="button" data-wysi="ul">List</button>' +
            '<button type="button" data-wysi="link">Link</button>' +
          '</div>' +
          '<textarea class="kv-textarea kv-wysi-textarea" name="synopsis" id="kv-synopsis" required>' + escapeHtml(f.synopsis || '') + '</textarea>' +
        '</label>' +
        '<label style="grid-column:1/-1;">URL Cover Blogger<input class="kv-input" name="cover" value="' + escapeHtml(f.coverBloggerUrl || '') + '" placeholder="https://blogger.googleusercontent.com/..." style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Genre (pisahkan dengan koma)<input class="kv-input" name="genres" value="' + escapeHtml(f.genresText || '') + '" placeholder="Aksi, Fantasi" style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<div style="display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap;">' +
          '<label>Tipe<select class="kv-select" name="type">' + ['Manga', 'Manhwa', 'Manhua'].map(function (t) { return '<option value="' + t + '"' + (f.type === t ? ' selected' : '') + '>' + t + '</option>'; }).join('') + '</select></label>' +
          '<label>Status<select class="kv-select" name="status">' + ['Ongoing', 'Tamat', 'Hiatus'].map(function (s) { return '<option value="' + s + '"' + (f.status === s ? ' selected' : '') + '>' + s + '</option>'; }).join('') + '</select></label>' +
          '<label>Rating 0-10<input class="kv-input kv-mono" name="rating" type="number" step="0.1" min="0" max="10" value="' + (f.rating !== '' && f.rating != null ? f.rating : '') + '" style="width:110px;display:block;margin-top:4px;"/></label>' +
        '</div>' +
      '</div>' +
      '<div style="display:flex;gap:20px;margin:14px 0;flex-wrap:wrap;">' +
        '<label style="display:flex;align-items:center;gap:8px;"><input type="checkbox" name="featured"' + (f.featured ? ' checked' : '') + '/> Manga unggulan (banner beranda)</label>' +
        '<label style="display:flex;align-items:center;gap:8px;"><input type="checkbox" name="recommended"' + (f.recommended ? ' checked' : '') + '/> Rekomendasi redaksi</label>' +
      '</div>' +
      '<div id="kv-manga-form-err" style="color:var(--kv-danger);font-size:0.8125rem;min-height:1.2em;margin-bottom:10px;"></div>' +
      '<button class="kv-btn kv-btn-primary" type="submit">' + (f.id ? 'Simpan Perubahan' : 'Publikasikan Manga') + '</button>' +
    '</form>';
  }

  function renderAdminChapterList() {
    if (!state.data.manga.length) {
      return '<div class="kv-stat-box" style="margin-top:16px;"><p style="color:var(--kv-text-muted);margin:0;">Tambahkan manga terlebih dahulu di tab Manga sebelum mengelola chapter.</p></div>';
    }
    if (!state.adminChapterMangaId || !mangaById(state.adminChapterMangaId)) state.adminChapterMangaId = state.data.manga[0].id;
    var sel = state.adminChapterMangaId;
    var mangaSelect = '<select id="kv-ch-manga" class="kv-select" aria-label="Pilih manga">' +
      state.data.manga.map(function (m) { return '<option value="' + escapeHtml(m.id) + '"' + (m.id === sel ? ' selected' : '') + '>' + escapeHtml(m.title) + '</option>'; }).join('') +
    '</select>';
    var chs = state.data.chapters.filter(function (c) { return c.mangaId === sel; }).sort(function (a, b) { return a.number - b.number; });
    var cards = chs.map(function (c, i) {
      var uploaded = c.pages.filter(function (p) { return p.bloggerUrl; }).length;
      var pct = c.pages.length ? Math.round((uploaded / c.pages.length) * 100) : 0;
      return '<div class="kv-admin-chapter-card">' +
        '<div class="kv-admin-chapter-card-head">' +
          '<span class="kv-badge kv-mono">Ch. ' + c.number + '</span>' +
          '<span class="kv-admin-chapter-card-title">' + escapeHtml(c.title || '(tanpa judul)') + '</span>' +
          '<span class="kv-admin-chapter-card-date">' + escapeHtml(c.publishedAt || '-') + '</span>' +
        '</div>' +
        '<div class="kv-admin-chapter-card-progress">' +
          '<div class="kv-admin-chapter-card-bar"><div class="kv-admin-chapter-card-barfill" style="width:' + pct + '%;"></div></div>' +
          '<span class="kv-mono">' + uploaded + '/' + c.pages.length + ' halaman (' + pct + '%)</span>' +
        '</div>' +
        '<div class="kv-admin-chapter-card-actions">' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-move-chapter" data-mid="' + escapeHtml(sel) + '" data-id="' + escapeHtml(c.id) + '" data-dir="up"' + (i === 0 ? ' disabled' : '') + ' aria-label="Naikkan urutan chapter">Naik</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-move-chapter" data-mid="' + escapeHtml(sel) + '" data-id="' + escapeHtml(c.id) + '" data-dir="down"' + (i === chs.length - 1 ? ' disabled' : '') + ' aria-label="Turunkan urutan chapter">Turun</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-edit-chapter" data-id="' + escapeHtml(c.id) + '">Ubah</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-preview-chapter" data-slug="' + escapeHtml((mangaById(sel) || {}).slug || '') + '" data-cid="' + escapeHtml(c.id) + '">Preview</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-danger-ghost" data-action="admin-delete-chapter" data-id="' + escapeHtml(c.id) + '">Hapus</button>' +
        '</div>' +
      '</div>';
    }).join('');
    return '<div class="kv-toolbar">' +
        (state.adminChapterFullId ? '<button type="button" class="kv-btn kv-btn-ghost" data-action="admin-close-chapters">Kembali ke Daftar Manga</button>' : '') +
        mangaSelect +
        '<button type="button" class="kv-btn kv-btn-primary" data-action="admin-new-chapter">+ Tambah Chapter</button>' +
      '</div>' +
      (cards ? '<div class="kv-admin-chapter-card-list">' + cards + '</div>' : '<p class="kv-admin-empty" style="margin-top:16px;">Belum ada chapter untuk manga ini.</p>');
  }

  function renderAdminChapterForm() {
    var f = state.adminChapterForm;
    f.pages = f.pages || [];
    var pagesRows = f.pages.map(function (p, i) {
      return '<tr>' +
        '<td class="kv-mono">' + (i + 1) + '</td>' +
        '<td>' + (p.bloggerUrl
          ? '<img class="kv-page-thumb" src="' + escapeHtml(p.bloggerUrl) + '" alt="Preview halaman ' + (i + 1) + '"/>'
          : '<div class="kv-page-thumb" style="display:flex;align-items:center;justify-content:center;font-size:0.625rem;color:var(--kv-text-muted);">' + (p.telegramFileId ? 'TG OK' : '-') + '</div>') + '</td>' +
        '<td class="kv-mono" style="font-size:0.75rem;">' + escapeHtml(p.fileName) +
          '<div style="color:var(--kv-text-muted);">' + escapeHtml(p.status || '-') + '<br/>TG: ' + escapeHtml(p.telegramFileId ? String(p.telegramFileId).slice(0, 16) + '...' : '-') + ' &middot; Proxy: ' + (p.bloggerUrl ? 'OK' : '-') + '</div></td>' +
        '<td><div style="display:flex;gap:6px;flex-wrap:wrap;">' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-page-move" data-idx="' + i + '" data-dir="up"' + (i === 0 ? ' disabled' : '') + ' aria-label="Naikkan urutan halaman">Naik</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-page-move" data-idx="' + i + '" data-dir="down"' + (i === f.pages.length - 1 ? ' disabled' : '') + ' aria-label="Turunkan urutan halaman">Turun</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-danger-ghost" data-action="admin-page-remove" data-idx="' + i + '">Hapus</button>' +
        '</div></td>' +
      '</tr>';
    }).join('');
     return '<form id="kv-chapter-form" class="kv-card" style="margin-top:16px;" novalidate>' +
      '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:14px;">' +
        '<h2 class="kv-section-title">' + (f.id ? 'Ubah Chapter' : 'Tambah Chapter Baru') + '</h2>' +
        '<button type="button" class="kv-btn kv-btn-ghost" data-action="admin-cancel-form">Batal</button>' +
      '</div>' +
      '<input type="hidden" name="id" value="' + escapeHtml(f.id || '') + '"/>' +
      '<div class="kv-form-grid">' +
        '<label>Manga *<select class="kv-select" name="mangaId" id="kv-ch-form-manga" style="width:100%;display:block;margin-top:4px;">' +
          state.data.manga.map(function (m) { return '<option value="' + escapeHtml(m.id) + '"' + (m.id === f.mangaId ? ' selected' : '') + '>' + escapeHtml(m.title) + '</option>'; }).join('') +
        '</select></label>' +
        '<label>Nomor Chapter *<input class="kv-input kv-mono" name="number" type="number" min="1" step="1" value="' + escapeHtml(f.number) + '" required style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Judul Chapter<input class="kv-input" name="title" value="' + escapeHtml(f.title || '') + '" style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Tanggal Publikasi<input class="kv-input kv-mono" name="publishedAt" type="date" value="' + escapeHtml(f.publishedAt || today()) + '" style="width:100%;display:block;margin-top:4px;"/></label>' +
      '</div>' +
      '<div style="margin:16px 0 8px;">' +
        '<h3 style="margin:0 0 8px;font-size:0.9375rem;">Halaman Gambar (Penyimpanan Telegram)</h3>' +
        '<div id="kv-dropzone" class="kv-dropzone" tabindex="0" role="button" aria-label="Seret gambar ke sini atau klik untuk memilih">' +
          '<div class="ico">📁</div>' +
          '<div><strong>Seret gambar ke sini</strong> atau klik untuk memilih</div>' +
          '<div style="font-size:.75rem;margin-top:4px;">JPEG/PNG/WebP, maks 3 MiB per berkas</div>' +
        '</div>' +
        '<input id="kv-ch-files" type="file" accept="image/jpeg,image/png,image/webp" multiple class="kv-input" style="display:none;"/>' +
        '<p style="color:var(--kv-text-muted);font-size:0.75rem;margin:6px 0 0;">Setiap file dikirim ke Vercel <code>/api/admin/upload-dual</code> dan disimpan sebagai dokumen Telegram. Reader menayangkan gambar melalui endpoint proxy Vercel. Batas 3 MiB per berkas.</p>' +
      '</div>' +
      (f.pages.length
        ? '<div class="kv-table-wrap" style="margin-top:12px;"><table class="kv-table"><thead><tr><th>Urut</th><th>Preview</th><th>Berkas &amp; Status</th><th>Aksi</th></tr></thead><tbody>' + pagesRows + '</tbody></table></div>'
        : '<p style="color:var(--kv-text-muted);font-size:0.875rem;">Belum ada halaman. Pilih satu atau beberapa gambar sekaligus.</p>') +
      '<div id="kv-chapter-form-err" style="color:var(--kv-danger);font-size:0.8125rem;min-height:1.2em;margin:12px 0 10px;"></div>' +
      '<button class="kv-btn kv-btn-primary" type="submit">' + (f.id ? 'Simpan Perubahan' : 'Publikasikan Chapter') + '</button>' +
    '</form>';
  }

  function renderAdminComments() {
    var myDisplayName = state.user ? currentDisplayName(state.user.name) : 'Pengguna';
    var opts = [['Semua', 'Semua'], ['pending', 'Menunggu'], ['approved', 'Disetujui'], ['rejected', 'Ditolak']];
    var list = state.data.comments.filter(function (c) { return state.commentFilter === 'Semua' || c.status === state.commentFilter; });
    var cards = list.map(function (c) {
      var m = mangaById(c.mangaId);
      var ch = c.chapterId ? state.data.chapters.filter(function (x) { return x.id === c.chapterId; })[0] : null;
      var authorName = (state.user && c.userId === state.user.id) ? myDisplayName : (c.authorName || 'Anonim');
      var avatar = c.authorAvatar ? '<img src="' + escapeHtml(c.authorAvatar) + '" alt="" class="kv-admin-comment-avatar" referrerpolicy="no-referrer"/>' : '<div class="kv-admin-comment-avatar kv-admin-comment-avatar-fallback">' + escapeHtml(String(authorName || '?').charAt(0).toUpperCase()) + '</div>';
      var badge = c.status === 'approved' ? '<span class="kv-badge kv-badge-ok">Disetujui</span>'
        : c.status === 'pending' ? '<span class="kv-badge kv-badge-pending">Menunggu</span>'
        : '<span class="kv-badge kv-badge-reject">Ditolak</span>';
      var pinBtn = '<button type="button" class="kv-btn kv-btn-sm ' + (c.pinned ? 'kv-btn-primary' : 'kv-btn-ghost') + '" data-action="admin-pin-comment" data-id="' + escapeHtml(c.id) + '">' + (c.pinned ? 'Lepas Pin' : 'Sematkan') + '</button>';
      var actions = '<div class="kv-admin-comment-actions">' +
        (c.status !== 'approved' ? '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-set-comment" data-id="' + escapeHtml(c.id) + '" data-status="approved">Setujui</button>' : '') +
        (c.status !== 'rejected' ? '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-set-comment" data-id="' + escapeHtml(c.id) + '" data-status="rejected">Tolak</button>' : '') +
        pinBtn +
        '<button type="button" class="kv-btn kv-btn-sm kv-btn-danger-ghost" data-action="admin-delete-comment" data-id="' + escapeHtml(c.id) + '">Hapus</button>' +
      '</div>';
      return '<div class="kv-admin-comment-card' + (c.pinned ? ' is-pinned' : '') + '">' +
        '<div class="kv-admin-comment-head">' +
          avatar +
          '<div class="kv-admin-comment-meta">' +
            '<div class="kv-admin-comment-author">' + escapeHtml(authorName) + (c.pinned ? ' <span class="kv-comment-pinned">Disematkan</span>' : '') + '</div>' +
            '<div class="kv-admin-comment-sub">' + escapeHtml(m ? m.title : '(manga dihapus)') + (ch ? ' · Ch. ' + escapeHtml(ch.number) : '') + ' · ' + escapeHtml(c.createdAt || '') + '</div>' +
          '</div>' +
          badge +
        '</div>' +
        '<div class="kv-admin-comment-body">' + escapeHtml(c.content) + (c.imageUrl ? '<div><img class="kv-admin-comment-img" src="' + escapeHtml(c.imageUrl) + '" alt="" loading="lazy" referrerpolicy="no-referrer"/></div>' : '') + '</div>' +
        actions +
      '</div>';
    }).join('');
    var filterButtons = '<div class="kv-admin-comment-filters">' +
      opts.map(function (o) {
        return '<button type="button" class="kv-btn kv-btn-sm ' + (state.commentFilter === o[0] ? 'kv-btn-primary' : 'kv-btn-ghost') + '" data-action="admin-comment-filter" data-filter="' + o[0] + '">' + o[1] + ' <span class="kv-admin-comment-count">' + state.data.comments.filter(function (c) { return o[0] === 'Semua' || c.status === o[0]; }).length + '</span></button>';
      }).join('') +
    '</div>';
    return '<div class="kv-admin-comments">' +
      filterButtons +
      (cards ? '<div class="kv-admin-comment-list">' + cards + '</div>' : '<p class="kv-admin-empty">Tidak ada komentar.</p>') +
    '</div>';
  }

   function loadAdminAnalytics(from, to) {
     if (!CONFIG.API_BASE_URL || !state.adminToken) return;
     var f = from || (state.analyticsFrom || '');
     var t = to || (state.analyticsTo || '');
     if (!f || !t) return;
     fetch(CONFIG.API_BASE_URL + '/api/analytics?from=' + encodeURIComponent(f) + '&to=' + encodeURIComponent(t), { headers: { 'Authorization': 'Bearer ' + state.adminToken } })
       .then(function (r) { if (!r.ok) throw new Error('Gagal memuat analitik.'); return r.json(); })
       .then(function (res) { state.analyticsData = res; render(); })
       .catch(function () { state.analyticsData = null; });
   }

   function loadAdminUsers() {

    if (!CONFIG.API_BASE_URL || !state.adminToken) return;
    fetch(CONFIG.API_BASE_URL + '/api/admin/users', { headers: { 'Authorization': 'Bearer ' + state.adminToken } })
      .then(function (r) { if (!r.ok) throw new Error('Gagal memuat pengguna.'); return r.json(); })
      .then(function (res) { state.usersCache = res.users || []; render(); })
      .catch(function () { state.usersCache = []; });
  }

  function renderAdminUsers() {
    if (state.usersCache === undefined) { state.usersCache = null; loadAdminUsers(); }
    if (state.usersCache === null) return '<div class="kv-card"><p style="color:var(--kv-text-muted);">Memuat pengguna...</p></div>';
    var rows = state.usersCache.map(function (u) {
      var isSelf = state.user && state.user.id === u.id;
      var avatar = u.avatar || ('https://api.dicebear.com/7.x/initials/svg?seed=' + encodeURIComponent(u.name));
      return '<div class="kv-user-card">' +
        '<div class="kv-user-card-head">' +
          '<img class="kv-user-avatar" src="' + escapeHtml(avatar) + '" alt=""/>' +
          '<div class="kv-user-meta">' +
            '<div class="kv-user-name">' + escapeHtml(u.name) + (isSelf ? ' <span class="kv-user-self">(Anda)</span>' : '') + '</div>' +
            '<div class="kv-user-email">' + escapeHtml(u.email || '-') + '</div>' +
          '</div>' +
          '<span class="kv-role-badge ' + escapeHtml(u.role) + '">' + escapeHtml(u.role) + '</span>' +
        '</div>' +
        '<div class="kv-user-card-body">' +
          '<div class="kv-user-row"><span>Provider</span><strong>' + escapeHtml(u.provider || '-') + '</strong></div>' +
          '<div class="kv-user-row"><span>Dibuat</span><strong>' + escapeHtml(u.createdAt || '-') + '</strong></div>' +
        '</div>' +
        '<div class="kv-user-card-actions">' +
          '<select class="kv-input kv-user-role" data-action="admin-user-role" data-id="' + escapeHtml(u.id) + '">' +
            '<option value="member"' + (u.role === 'member' ? ' selected' : '') + '>member</option>' +
            '<option value="admin"' + (u.role === 'admin' ? ' selected' : '') + '>admin</option>' +
          '</select>' +
          (isSelf ? '' : '<button type="button" class="kv-btn kv-btn-danger-ghost" data-action="admin-delete-user" data-id="' + escapeHtml(u.id) + '">Hapus</button>') +
        '</div>' +
      '</div>';
    }).join('');
    return '<div class="kv-card"><h3>Daftar Pengguna (' + state.usersCache.length + ')</h3>' +
      (rows ? '<div class="kv-user-grid">' + rows + '</div>' : '<p class="kv-admin-empty">Belum ada pengguna.</p>') +
    '</div>';
  }

  function changeUserRoleAdmin(userId, role) {
    if (!CONFIG.API_BASE_URL || !state.adminToken) { alert('Backend tidak terhubung.'); return; }
    fetch(CONFIG.API_BASE_URL + '/api/admin/user-role', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
      body: JSON.stringify({ id: userId, role: role })
    }).then(function (r) {
      return r.json().then(function (j) { return { ok: r.ok, status: r.status, body: j }; });
    }).then(function (res) {
      if (res.ok) {
        if (state.usersCache) {
          state.usersCache = state.usersCache.map(function (u) { if (u.id === userId) { u.role = role; } return u; });
        }
        alert('Role berhasil diubah menjadi ' + role + '.');
      } else {
        alert('Gagal: ' + (res.body && res.body.error ? res.body.error : ('HTTP ' + res.status)));
      }
      state.usersCache = undefined;
      loadAdminUsers();
    }).catch(function (e) { alert('Error jaringan: ' + e.message); });
  }
  function deleteUserAdmin(userId) {
    if (!confirm('Hapus pengguna ini?')) return;
    if (!CONFIG.API_BASE_URL || !state.adminToken) { toast('Backend tidak terhubung.', 'error'); return; }
    fetch(CONFIG.API_BASE_URL + '/api/admin/delete-user', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
      body: JSON.stringify({ id: userId })
    }).then(function (r) { if (!r.ok) return r.json().then(function (j) { throw new Error(j.error || 'Gagal menghapus pengguna.'); }); return r.json(); })
      .then(function () { toast('Pengguna dihapus.', 'success'); state.usersCache = undefined; loadAdminUsers(); })
      .catch(function (e) { toast(e.message, 'error'); });
  }

  function persistSiteSettings(values) {
    var current = {};
    try { current = Object.assign({}, JSON.parse(localStorage.getItem('kv_site_settings') || '{}'), (state.data && state.data.settings) ? state.data.settings : {}); } catch (e) { current = {}; }
    values = Object.assign({}, current, values);
    var isBackend = CONFIG.API_BASE_URL && state.adminToken;
    var done = function () { toast('Pengaturan logo & nama disimpan.', 'ok'); render(); };
    if (isBackend) {
      return fetch(CONFIG.API_BASE_URL + '/api/admin/settings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
        body: JSON.stringify(values)
      }).then(function (r) {
        return r.json().then(function (j) {
          if (!r.ok) throw new Error((j && j.error) || ('HTTP ' + r.status));
          return j.settings;
        });
      }).then(function (saved) {
        state.data.settings = saved;
        try { localStorage.setItem('kv_site_settings', JSON.stringify(saved)); } catch (e) {}
        done();
      }).catch(function (err) {
        console.warn('Gagal menyimpan ke server, fallback ke browser:', err);
        try {
          localStorage.setItem('kv_site_settings', JSON.stringify(values));
          state.data.settings = values;
          toast('Gagal ke server, tersimpan di browser ini.', 'warn');
          render();
        } catch (e) {
          toast('Gagal menyimpan pengaturan: ' + err.message, 'error');
        }
      });
    }
    try {
      localStorage.setItem('kv_site_settings', JSON.stringify(values));
      state.data.settings = values;
      done();
    } catch (e) {
      toast('Gagal menyimpan pengaturan di browser.', 'warn');
    }
  }

  function resetSiteSettings() {
    persistSiteSettings({ siteName: '', siteTagline: '', logoUrl: '', contactEmail: '', brandMode: '', siteNameColor: '' });
  }

