          '<label style="grid-column:1/-1;">Email Kontak<input class="kv-input" name="contactEmail" type="email" value="' + contactValue + '" placeholder="redaksi@contoh.com"/></label>' +
          '<label>Tampilan Brand<select class="kv-select" name="brandMode">' +
            '<option value="logo-name"' + (brandModeValue === 'logo-name' ? ' selected' : '') + '>Logo + Nama</option>' +
            '<option value="logo-only"' + (brandModeValue === 'logo-only' ? ' selected' : '') + '>Hanya Logo</option>' +
            '<option value="name-only"' + (brandModeValue === 'name-only' ? ' selected' : '') + '>Hanya Nama</option>' +
          '</select></label>' +
          '<label>Warna Nama Situs<input class="kv-input" name="siteNameColor" type="color" value="' + (siteNameColorValue || '#6366f1') + '" style="height:38px;padding:2px 6px;"/></label>' +
          '<div class="kv-site-logo-preview">' + (logoValue ? '<img src="' + logoValue + '" alt="Preview logo"/>' : '<span>Belum ada logo</span>') + '</div>' +
          '<div style="display:flex;gap:10px;flex-wrap:wrap;grid-column:1/-1;">' +
            '<button type="button" class="kv-btn kv-btn-ghost" id="kv-logo-upload-btn">Unggah Logo</button>' +
            '<input id="kv-logo-file" type="file" accept="image/jpeg,image/png,image/webp" style="display:none;"/>' +
            '<button type="submit" class="kv-btn kv-btn-primary">Simpan Pengaturan</button>' +
