          '</div>' +
        '</form>' +
       '</div>' +
       '<div class="kv-card" style="margin-top:16px;">' +
         '<h2 class="kv-section-title" style="margin-bottom:4px;">Halaman Info</h2>' +
         '<p class="kv-admin-sub" style="margin-bottom:14px;">Kelola isi halaman Tentang, Kontak, Kebijakan Privasi, dan Ketentuan.</p>' +
         '<form id="kv-info-settings-form" class="kv-form-grid" novalidate>' +
           '<label style="grid-column:1/-1;">Tentang<textarea class="kv-textarea" name="aboutContent" rows="5" placeholder="Tulis tentang situs...">' + escapeHtml(siteSetting('aboutContent', '')) + '</textarea></label>' +
           '<label style="grid-column:1/-1;">Kontak<textarea class="kv-textarea" name="contactContent" rows="5" placeholder="Tulis kontak...">' + escapeHtml(siteSetting('contactContent', '')) + '</textarea></label>' +
           '<label style="grid-column:1/-1;">Kebijakan Privasi<textarea class="kv-textarea" name="privacyContent" rows="6" placeholder="Tulis kebijakan privasi...">' + escapeHtml(siteSetting('privacyContent', '')) + '</textarea></label>' +
           '<label style="grid-column:1/-1;">Ketentuan<textarea class="kv-textarea" name="termsContent" rows="6" placeholder="Tulis ketentuan penggunaan...">' + escapeHtml(siteSetting('termsContent', '')) + '</textarea></label>' +
           '<div style="grid-column:1/-1; display:flex; justify-content:flex-end;">' +
             '<button type="submit" class="kv-btn kv-btn-primary">Simpan Halaman Info</button>' +
