            var headers = { 'Content-Type': 'application/json' };
            if (state.adminToken) headers['Authorization'] = 'Bearer ' + state.adminToken;
            fetch(CONFIG.API_BASE_URL + '/api/comment', {
              method: 'POST',
              headers: headers,
              body: JSON.stringify({ mangaId: mangaId, chapterId: chapterId, parentId: parentId, replyTo: replyTo, authorName: authorName, authorAvatar: authorAvatar, content: content })
            }).catch(function () { toast('Balasan tersimpan lokal, gagal terkirim ke server.', 'warn'); });
         }
         render();
       };
     });

     var imgFile = document.getElementById('kv-comment-image-file');
     if (imgFile) {
       imgFile.onchange = function (e) {
         var file = e.target.files && e.target.files[0];
         var targetForm = state.imageTargetForm;
         state.imageTargetForm = null;
          if (!file || !targetForm) return;
          if (!CONFIG.API_BASE_URL) { toast('Upload gambar butuh backend yang terhubung.', 'warn'); return; }
          var btn = state.commentImageUploadingBtn;
          if (btn) { btn.disabled = true; btn.innerHTML = '<span class="kv-spinner"></span>'; }
          var reader = new FileReader();

         reader.onload = function () {
           var headers = { 'Content-Type': 'application/json' };
           if (state.adminToken) headers['Authorization'] = 'Bearer ' + state.adminToken;
           fetch(CONFIG.API_BASE_URL + '/api/comment/image', {
             method: 'POST',
             headers: headers,
             body: JSON.stringify({ fileName: file.name, mimeType: file.type, dataBase64: reader.result })
           }).then(function (r) {
             return r.json().then(function (res) {
               if (!r.ok) throw new Error(res.error || ('HTTP ' + r.status));
               return res;
             });
            }).then(function (res) {
              var textarea = targetForm.querySelector('textarea');
              state.commentImageIndex = (state.commentImageIndex || 0) + 1;
              var token = '[gambar' + state.commentImageIndex + ']';
              if (textarea) {
                var start = textarea.selectionStart || 0;
                var end = textarea.selectionEnd || textarea.value.length;
                var before = textarea.value.slice(0, start);
                var after = textarea.value.slice(end);
                textarea.value = before + token + after;
                var pos = before.length + token.length;
                textarea.focus();
                textarea.setSelectionRange(pos, pos);
              }
              state.commentImageMap = state.commentImageMap || {};
              state.commentImageMap[token] = res.url || '';
              toast('Gambar diunggah dan disisipkan ke komentar.', 'ok');
             }).catch(function (err) { toast('Gagal upload gambar: ' + err.message, 'error'); })
             .finally(function () {
               var btn = state.commentImageUploadingBtn;
               if (btn) { btn.disabled = false; btn.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg>'; }
               state.commentImageUploadingBtn = null;
             });

         };
         reader.readAsDataURL(file);
       };
     }

     /* --- Binding panel admin --- */
    var aSearch = document.getElementById('kv-admin-manga-search');
    if (aSearch) aSearch.oninput = function (e) { state.adminSearch = e.target.value; state.adminRefocusSearch = true; render(); };
    if (aSearch && state.adminRefocusSearch) {
      state.adminRefocusSearch = false;
      aSearch.focus();
      var aLen = aSearch.value.length;
      aSearch.setSelectionRange(aLen, aLen);
    }
     var mForm = document.getElementById('kv-manga-form');
     if (mForm) mForm.onsubmit = function (e) { e.preventDefault(); saveMangaForm(mForm); };
     document.querySelectorAll('[data-wysi]').forEach(function (btn) {
       btn.onclick = function () {
         var ta = document.getElementById('kv-synopsis');
         if (!ta) return;
         var tag = btn.getAttribute('data-wysi');
         var start = ta.selectionStart, end = ta.selectionEnd;
         var sel = ta.value.slice(start, end);
         var wrap = { bold: ['**', '**'], italic: ['*', '*'], h3: ['### ', ''], ul: ['- ', ''], link: ['[', '](url)'] }[tag];
         if (!wrap) return;
         var text = wrap[0] + (sel || 'teks') + wrap[1];
         ta.value = ta.value.slice(0, start) + text + ta.value.slice(end);
         ta.focus();
         ta.selectionStart = start + wrap[0].length;
         ta.selectionEnd = start + wrap[0].length + (sel || 'teks').length;
       };
     });
    var chMangaSel = document.getElementById('kv-ch-manga');
    if (chMangaSel) chMangaSel.onchange = function (e) { state.adminChapterMangaId = e.target.value; render(); };
    var chForm = document.getElementById('kv-chapter-form');
    if (chForm) chForm.onsubmit = function (e) { e.preventDefault(); saveChapterForm(chForm); };
    var chFormSel = document.getElementById('kv-ch-form-manga');
    if (chFormSel) chFormSel.onchange = function (e) { if (state.adminChapterForm) state.adminChapterForm.mangaId = e.target.value; };
     var chFiles = document.getElementById('kv-ch-files');
     if (chFiles) chFiles.onchange = function (e) {
       var files = Array.prototype.slice.call(e.target.files);
       e.target.value = '';
       if (files.length) uploadPageFiles(files);
     };
     var dropzone = document.getElementById('kv-dropzone');
     if (dropzone) {
       dropzone.onclick = function () { if (chFiles) chFiles.click(); };
       dropzone.ondragover = function (e) { e.preventDefault(); dropzone.classList.add('drag'); };
       dropzone.ondragleave = function () { dropzone.classList.remove('drag'); };
       dropzone.ondrop = function (e) {
         e.preventDefault();
         dropzone.classList.remove('drag');
         var files = [];
         if (e.dataTransfer && e.dataTransfer.files) files = Array.prototype.slice.call(e.dataTransfer.files);
         if (files.length) uploadPageFiles(files);
       };
     }
     var cFilter = document.getElementById('kv-comment-filter');
     if (cFilter) cFilter.onchange = function (e) { state.commentFilter = e.target.value; render(); };
     if (!window.__adminChangeDelegated) {
       window.__adminChangeDelegated = true;
       document.addEventListener('change', function (e) {
         var sel = e.target && e.target.closest ? e.target.closest('select[data-action="admin-user-role"]') : null;
         if (sel) changeUserRoleAdmin(sel.getAttribute('data-id'), sel.value);
       });
     }
  }

  document.addEventListener('click', function (e) {
    var routeLink = e.target.closest('a[href^="/"], a[href^="#/"]');
    if (!routeLink || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    e.preventDefault();
    navigate(routeLink.getAttribute('href'));
  });

  document.addEventListener('click', function (e) {
    var insideDropdown = e.target && e.target.closest ? e.target.closest('.kv-dropdown, .kv-dropdown-btn') : null;
    if (!insideDropdown && state.openCatalogDropdown) {
      state.openCatalogDropdown = null;
      render();
      return;
    }
    var trigger = e.target.closest && e.target.closest('.kv-dropdown-btn');
    if (trigger) {
      var container = trigger.closest('.kv-dropdown');
      var name = container ? container.getAttribute('data-dropdown') : null;
      state.openCatalogDropdown = state.openCatalogDropdown === name ? null : name;
      render();
      return;
    }
    var el = e.target.closest('[data-action]');
    if (!el) return;
    var act = el.getAttribute('data-action');
    if (act === 'toggle-theme') { state.theme = state.theme === 'dark' ? 'light' : 'dark'; applyTheme(); render(); }
    else if (act === 'oauth-login') {
      if (!CONFIG.API_BASE_URL) { toast('Backend Vercel belum dikonfigurasi.', 'warn'); return; }
      var provider = el.getAttribute('data-provider');
      if (provider !== 'google' && provider !== 'discord') return;
      var returnOrigin = window.location.origin;
      window.location.assign(CONFIG.API_BASE_URL + '/api/auth/' + provider + '/start?return_to=' + encodeURIComponent(returnOrigin));
    }
    else if (act === 'toggle-mobile-menu') { state.mobileMenuOpen = !state.mobileMenuOpen; render(); }
    else if (act === 'open-manga') { navigate('#/manga/' + el.getAttribute('data-slug')); }
    else if (act === 'reply-comment') { var rid = el.getAttribute('data-id'); state.replyingTo = state.replyingTo === rid ? null : rid; render(); }
    else if (act === 'upvote-comment') { upvoteCommentLocal(el.getAttribute('data-id')); }
    else if (act === 'toggle-replies') {
      var rid = el.getAttribute('data-id');
      if (!state.expandedComments) state.expandedComments = {};
      state.expandedComments[rid] = !state.expandedComments[rid];
      render();
    }
    else if (act === 'admin-pin-comment') { adminPinComment(el.getAttribute('data-id')); }
    else if (act === 'admin-delete-comment') {
      var dc = state.data.comments.filter(function (x) { return x.id === el.getAttribute('data-id'); })[0];
      if (dc) confirmDelete('comment', dc.id, 'Hapus komentar dari ' + (dc.authorName || 'Pembaca') + '?', 'Hapus Komentar');
    }
    else if (act === 'chapter-reaction') { chapterReactionLocal(el.getAttribute('data-id'), el.getAttribute('data-reaction')); }
    else if (act === 'open-reader') { navigate('#/baca/' + el.getAttribute('data-slug') + '/' + el.getAttribute('data-cid')); }
    else if (act === 'quick-genre') { var genre = el.getAttribute('data-genre'); state.filterGenres = genre && genre !== 'Semua' ? [genre] : []; state.openCatalogDropdown = 'genre'; state.page = 1; navigate('#/archive'); }
    else if (act === 'toggle-ch-sort') { state.chapterSortAsc = !state.chapterSortAsc; render(); }
    else if (act === 'clear-genres') { state.filterGenres = []; state.page = 1; state.openCatalogDropdown = 'genre'; render(); }
    else if (act === 'close-catalog-dropdowns') { state.openCatalogDropdown = null; render(); }
    else if (act === 'set-filter-type') { state.filterType = el.getAttribute('data-value') || 'Semua Tipe'; state.page = 1; state.openCatalogDropdown = null; render(); }
    else if (act === 'set-filter-status') { state.filterStatus = el.getAttribute('data-value') || 'Semua Status'; state.page = 1; state.openCatalogDropdown = null; render(); }
    else if (act === 'set-sort') { state.sortBy = el.getAttribute('data-value') || 'terbaru'; state.openCatalogDropdown = null; render(); }
    else if (act === 'toggle-reader-mode') { var mode = el.getAttribute('data-mode'); state.readerMode = (mode === 'vertical' || mode === 'paged') ? mode : (state.readerMode === 'vertical' ? 'paged' : 'vertical'); state.currentPageIdx = 0; render(); }
    else if (act === 'scroll-reader-up') { window.scrollBy({ top: -Math.round(window.innerHeight * 0.8), behavior: 'smooth' }); }
    else if (act === 'scroll-reader-down') { window.scrollBy({ top: Math.round(window.innerHeight * 0.8), behavior: 'smooth' }); }
     else if (act === 'toggle-auto-scroll') { toggleAutoScroll(); }
     else if (act === 'set-reader-theme') { state.theme = el.getAttribute('data-theme'); applyTheme(); render(); }
     else if (act === 'set-scroll-speed') { state.autoScrollSpeed = parseFloat(el.getAttribute('data-speed')) || 2.5; render(); }
    else if (act === 'toggle-reader-settings') { state.readerSettingsOpen = !state.readerSettingsOpen; state.readerMenuOpen = false; render(); }
    else if (act === 'scroll-banner-dot') {
      var bTrack = document.getElementById('kv-banner-track');
      var dotIndex = Number(el.getAttribute('data-index') || 0);
      if (bTrack && bTrack.children[dotIndex]) {
        bTrack.children[dotIndex].scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });
        setBannerDotsActive(dotIndex);
      }
    }
    else if (act === 'toggle-reader-menu') { state.readerMenuOpen = !state.readerMenuOpen; state.readerSettingsOpen = false; render(); }
    else if (act === 'close-reader-panels') { state.readerMenuOpen = false; state.readerSettingsOpen = false; render(); }
    else if (act === 'toggle-fullscreen') {
      if (document.fullscreenElement) { document.exitFullscreen().catch(function () {}); }
      else if (document.documentElement.requestFullscreen) { document.documentElement.requestFullscreen().catch(function () {}); }
    }

    else if (act === 'prev-page') { state.currentPageIdx = Math.max(0, state.currentPageIdx - 1); render(); }
    else if (act === 'next-page') { var max = Number(el.getAttribute('data-max')) - 1; state.currentPageIdx = Math.min(max, state.currentPageIdx + 1); render(); }
    else if (act === 'toggle-bookmark') {
      var id = el.getAttribute('data-id');
      var i = state.bookmarks.indexOf(id);
      if (i === -1) state.bookmarks.push(id); else state.bookmarks.splice(i, 1);
      localStorage.setItem('kv_bookmarks', JSON.stringify(state.bookmarks));
      render();
    }
    else if (act === 'retry-api') { state.error = null; syncFromApi(); }
     else if (act === 'set-comment-sort') { state.commentSort = el.getAttribute('data-sort'); render(); }
     else if (act === 'comment-image') {
       if (!state.user) { toast('Masuk terlebih dahulu untuk mengunggah gambar.', 'warn'); return; }
       state.imageTargetForm = el.closest('form');
       state.commentImageUploadingBtn = el;
       var fileInput = document.getElementById('kv-comment-image-file');
       if (fileInput) fileInput.click();
     }

    else if (act === 'admin-settings-reset') { resetSiteSettings(); }
    else if (act === 'toggle-admin-drawer') { state.adminDrawerOpen = !state.adminDrawerOpen; render(); }
    else if (act === 'close-admin-drawer') { state.adminDrawerOpen = false; render(); }
    else if (act === 'share-manga') {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(window.location.href).catch(function () {});
      }
      var prevLabel = el.textContent;
      el.textContent = 'Tautan Disalin';
      setTimeout(function () { el.textContent = prevLabel; }, 2000);
    }
    else if (act === 'toggle-edit-profile') { state.editingProfile = !state.editingProfile; render(); }
    else if (act === 'logout-user' || act === 'logout-admin') {
      state.user = null;
      state.adminToken = '';
      state.usersCache = undefined;
      state.data = { manga: [], chapters: [], comments: [] };
      localStorage.removeItem('kv_session_token');
      localStorage.removeItem('kv_local_data');
      localStorage.removeItem('kv_profile_override');
      render();
      syncFromApi();
    }
    /* --- Aksi panel admin --- */
     else if (act === 'admin-tab') { state.adminTab = el.getAttribute('data-tab'); state.adminForm = null; state.adminChapterForm = null; state.adminChapterFullId = null; state.adminDrawerOpen = false; if (state.adminTab === 'pengguna') state.usersCache = undefined; render(); }
     else if (act === 'admin-comment-filter') { state.commentFilter = el.getAttribute('data-filter'); render(); }
     else if (act === 'admin-open-leaderboard') { state.adminTab = 'leaderboard'; state.adminDrawerOpen = false; render(); }
     else if (act === 'kv-traffic-refresh') {
       var from = document.getElementById('kv-traffic-from');
       var to = document.getElementById('kv-traffic-to');
       if (from && to && from.value && to.value && from.value > to.value) { alert('Tanggal awal tidak boleh melewati tanggal akhir.'); return; }
       state.analyticsFrom = from && from.value ? from.value : state.analyticsFrom;
       state.analyticsTo = to && to.value ? to.value : state.analyticsTo;
       state.analyticsData = undefined;
       loadAdminAnalytics(state.analyticsFrom, state.analyticsTo);
     }
    else if (act === 'admin-delete-user') { deleteUserAdmin(el.getAttribute('data-id')); }
    else if (act === 'admin-new-manga') { state.adminForm = blankManga(); state.adminTab = 'manga'; state.adminDrawerOpen = false; render(); }
    else if (act === 'admin-edit-manga') {
      var am = mangaById(el.getAttribute('data-id'));
      if (am) { state.adminForm = JSON.parse(JSON.stringify(am)); state.adminForm.genresText = (am.genres || []).join(', '); state.adminTab = 'manga'; state.adminDrawerOpen = false; render(); }
    }
    else if (act === 'admin-cancel-form') { state.adminForm = null; state.adminChapterForm = null; render(); }
    else if (act === 'admin-preview-manga') { navigate('#/manga/' + el.getAttribute('data-slug')); }
    else if (act === 'admin-delete-manga') {
      var dm = mangaById(el.getAttribute('data-id'));
      if (dm) confirmDelete('manga', dm.id, 'Hapus manga "' + dm.title + '" beserta seluruh chapter dan komentarnya?', 'Hapus Manga');
    }
     else if (act === 'admin-new-chapter') {
       if (el.getAttribute('data-id')) { state.adminChapterMangaId = el.getAttribute('data-id'); state.adminExpandedManga = el.getAttribute('data-id'); }
       if (!state.data.manga.length) { toast('Tambahkan manga terlebih dahulu di tab Manga.', 'warn'); }
        else { state.adminChapterForm = blankChapter(state.adminChapterMangaId); state.adminTab = 'manga'; state.adminDrawerOpen = false; render(); }
     }
    else if (act === 'admin-toggle-expand') {
      var expId = el.getAttribute('data-id');
      state.adminExpandedManga = state.adminExpandedManga === expId ? null : expId;
      render();
    }
      else if (act === 'admin-open-chapters') {
        state.adminChapterMangaId = el.getAttribute('data-id');
        state.adminChapterFullId = el.getAttribute('data-id');
        state.adminChapterForm = null;
        state.adminExpandedManga = el.getAttribute('data-id');
        state.adminTab = 'manga';
        state.adminDrawerOpen = false;
        render();
      }
      else if (act === 'admin-close-chapters') {
        state.adminChapterFullId = null;
        render();
      }

    else if (act === 'admin-edit-chapter') {
      var ec = chapterById(el.getAttribute('data-id'));
      if (ec) {
        state.adminChapterForm = JSON.parse(JSON.stringify(ec));
        state.adminChapterForm.pages = state.adminChapterForm.pages || [];
        state.adminChapterMangaId = ec.mangaId;
        state.adminTab = 'manga';
        render();
      }
    }
    else if (act === 'admin-move-chapter') { moveChapter(el.getAttribute('data-mid'), el.getAttribute('data-id'), el.getAttribute('data-dir')); }
    else if (act === 'admin-preview-chapter') { navigate('#/baca/' + el.getAttribute('data-slug') + '/' + el.getAttribute('data-cid')); }
    else if (act === 'admin-delete-chapter') {
      var dc = chapterById(el.getAttribute('data-id'));
      if (dc) confirmDelete('chapter', dc.id, 'Hapus Chapter ' + dc.number + ' ("' + (dc.title || 'tanpa judul') + '") beserta semua halamannya?', 'Hapus Chapter');
    }
    else if (act === 'admin-page-move') { movePage(Number(el.getAttribute('data-idx')), el.getAttribute('data-dir')); }
    else if (act === 'admin-page-remove') { removePage(Number(el.getAttribute('data-idx'))); }
    else if (act === 'admin-set-comment') { setCommentStatus(el.getAttribute('data-id'), el.getAttribute('data-status')); }
    else if (act === 'admin-delete-comment') {
      var cm = state.data.comments.filter(function (x) { return x.id === el.getAttribute('data-id'); })[0];
      if (cm) confirmDelete('comment', cm.id, 'Hapus komentar dari ' + cm.authorName + '?', 'Hapus Komentar');
    }
    else if (act === 'admin-reset-data') { confirmDelete('reset', '', 'Semua manga, chapter, dan komentar lokal akan dikembalikan ke data contoh.', 'Reset Data'); }
    else if (act === 'confirm-delete') { performConfirmedDelete(); }
    else if (act === 'cancel-delete') { state.pendingDelete = null; render(); }
  });

  // Shortcut reader: j/k untuk gulir, panah untuk ganti halaman, f untuk layar penuh
  document.addEventListener('keydown', function (e) {
    if (state.route !== 'reader') return;
    var t = e.target;
    if (t && (['INPUT', 'TEXTAREA', 'SELECT'].indexOf(t.tagName) !== -1)) return;
    var key = e.key.toLowerCase();
    if (key === 'j' || e.key === 'ArrowDown') { window.scrollBy({ top: 400, behavior: 'smooth' }); }
    else if (key === 'k' || e.key === 'ArrowUp') { window.scrollBy({ top: -400, behavior: 'smooth' }); }
    else if ((key === 'arrowleft' || key === 'arrowright' || e.key === ' ') && state.readerMode === 'paged') {
      var ch = chapterById(state.params && state.params.chapterId);
      var max = ch ? Math.max(0, (ch.pages || []).length - 1) : 0;
      if (key === 'arrowleft') state.currentPageIdx = Math.max(0, state.currentPageIdx - 1);
      else { state.currentPageIdx = Math.min(max, state.currentPageIdx + 1); if (e.key === ' ') e.preventDefault(); }
      render();
      window.scrollTo(0, 0);
    }
    else if (key === 'f') {
      if (document.fullscreenElement) { document.exitFullscreen().catch(function () {}); }
      else if (document.documentElement.requestFullscreen) { document.documentElement.requestFullscreen().catch(function () {}); }
    }
    else if (key === 'p') { toggleAutoScroll(); }
  });

  // Aksesibilitas: elemen interaktif custom (kartu/baris) dapat diaktifkan via Enter/Spasi
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && state.openCatalogDropdown) {
      state.openCatalogDropdown = null;
      render();
      return;
    }
    if (e.key !== 'Enter' && e.key !== ' ') return;
    var t = e.target;
    if (!t || !t.getAttribute) return;
    if (['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].indexOf(t.tagName) !== -1) return;
    if (!t.hasAttribute('data-action')) return;
    e.preventDefault();
    t.click();
  });


  function handleRouteChange() {
    stopAutoScroll();
    if (state.readerDockTimer) {
      clearInterval(state.readerDockTimer);
      state.readerDockTimer = null;
    }
    state.readerMenuOpen = false;
    state.readerSettingsOpen = false;
    state.mobileMenuOpen = false;
    state.commentNotice = null;
    parseRoute();
    render();
    window.scrollTo(0, 0);
  }

  // Toggle spoiler komentar saat diklik
  document.addEventListener('click', function (e) {
    var sp = e.target && e.target.closest ? e.target.closest('.kv-spoiler-toggle') : null;
    if (!sp) return;
    var box = sp.closest('.kv-spoiler');
    if (box) box.classList.toggle('open');
  });

  window.addEventListener('popstate', handleRouteChange);
  window.addEventListener('hashchange', handleRouteChange);

   applyTheme();
   parseRoute();
   initializeAuth();
   trackPageview();
 })();

